import subprocess,re
def out(args):
    return subprocess.check_output(["/workspace/executable"]+args, text=True)
for args in [["--list-fields"],["--list-fields=Python"],["--list-kinds-full"],["--list-kinds-full=Python"],["--list-roles"],["--list-extras"]]:
    s=out(args); lines=s.splitlines(); hdr=lines[0]
    cols=[(m.group(),m.start()) for m in re.finditer(r'\S+(?:\([^)]*\))?|\S+',hdr)]
    # Simpler split indexes searching tokens
    print(args, hdr)
    toks=hdr.split()
    idx=[]
    pos=0
    for t in toks:
        i=hdr.find(t,pos); idx.append((t,i)); pos=i+len(t)
    print(idx)
    for l in lines[1:3]:
        print([l[i:j] for (t,i),(_,j) in zip(idx, idx[1:]+[("end",len(l))])])
PY
"}

