{"command":"cat > /workspace/src/__main__.py <<'PYEOF'
#!/usr/bin/env python3
import sys, os, re, json, zlib, base64, fnmatch, subprocess, struct
from dataclasses import dataclass, field as dc_field

try:
    from data_blob import DATA_BLOB
except Exception:
    DATA_BLOB = ""
DATA = {}
try:
    if DATA_BLOB:
        DATA = json.loads(zlib.decompress(base64.b85decode(DATA_BLOB.encode())))
except Exception:
    DATA = {}
GLOBALS = DATA.get("globals", {})
PER_LANG = DATA.get("per_lang", {})

PROG = os.path.basename(sys.argv[0]) if sys.argv else "ctags"
VERSION_TEXT = GLOBALS.get("version", "Universal Ctags 6.2.0(1cdb801), Copyright (C) 2015-2025 Universal Ctags Team\nUniversal Ctags is derived from Exuberant Ctags.\nExuberant Ctags 5.8, Copyright (C) 1996-2009 Darren Hiebert\n  Compiled: Jun 11 2026, 22:09:24\n  URL: https://ctags.io/\n  Output version: 1.1\n  Optional compiled features: +wildcards, +regex, +iconv, +option-directory, +xpath, +json, +interactive, +sandbox, +yaml, +packcc, +optscript, +pcre2\n")

def eprint(*a):
    print(*a, file=sys.stderr)

def warn(msg):
    eprint(f"{PROG}: Warning: {msg}")

def err(msg):
    eprint(f"{PROG}: {msg}")

# ---------- derived language data ----------
LANG_ORDER = []
LANG_DISABLED = {}
for _line in GLOBALS.get("list_languages","").splitlines():
    _dis = _line.endswith(" [disabled]")
    _name = _line[:-len(" [disabled]")].strip() if _dis else _line.strip()
    if _name:
        LANG_ORDER.append(_name); LANG_DISABLED[_name]=_dis
LANG_BY_LOWER = {n.lower(): n for n in LANG_ORDER}
# additional parser names known but not listed? keep PER_LANG keys
for _n in PER_LANG:
    if _n not in LANG_BY_LOWER:
        LANG_ORDER.append(_n); LANG_BY_LOWER[_n.lower()]=_n; LANG_DISABLED[_n]=False

def canon_lang(name):
    if name is None: return None
    return LANG_BY_LOWER.get(str(name).lower())

def parse_mach(text):
    rows=[]
    for line in (text or "").splitlines():
        if not line or line.startswith("#"): continue
        rows.append(line.split("\t"))
    return rows

KINDS = {}          # lang -> {letter: dict, } 
KIND_BY_NAME = {}   # lang -> {name: dict}
KIND_ORDER_LISTKINDS = {}  # lang -> list of (letter, description, enabled_from_listkinds)
for lang, d in PER_LANG.items():
    km={}
    bn={}
    for r in parse_mach(d.get("machinable_kinds_full","")):
        if len(r) < 8: continue
        letter,name,enabled,refonly,nroles,master,ver,desc = r[:8]
        kd={"letter":letter,"name":name,"enabled":enabled=="yes","refonly":refonly=="yes","nroles":nroles,"master":master,"ver":ver,"description":desc}
        km[letter]=kd; bn[name]=kd
    KINDS[lang]=km; KIND_BY_NAME[lang]=bn
    lst=[]
    for line in d.get("kinds","").splitlines():
        if not line: continue
        # format: letter, two spaces, desc [off]
        letter=line[0]
        rest=line[1:].lstrip()
        off=False
        if rest.endswith(" [off]"):
            off=True; rest=rest[:-len(" [off]")]
        lst.append((letter,rest,not off))
    KIND_ORDER_LISTKINDS[lang]=lst

FIELDS_COMMON=[]
FIELDS_LANG={}
for r in parse_mach(GLOBALS.get("machinable_list_fields","")):
    if len(r)>=9 and r[3]=="NONE":
        FIELDS_COMMON.append({"letter":r[0],"name":r[1],"enabled":r[2]=="yes","language":r[3],"jstype":r[4],"fixed":r[5],"op":r[6],"ver":r[7],"description":r[8]})
for lang,d in PER_LANG.items():
    fl=[]
    for r in parse_mach(d.get("machinable_fields","")):
        if len(r)>=9:
            fl.append({"letter":r[0],"name":r[1],"enabled":r[2]=="yes","language":r[3],"jstype":r[4],"fixed":r[5],"op":r[6],"ver":r[7],"description":r[8]})
    FIELDS_LANG[lang]=fl

EXTRAS_COMMON=[]
EXTRAS_LANG={}
for r in parse_mach(GLOBALS.get("machinable_list_extras","")):
    if len(r)>=7 and r[3]=="NONE":
        EXTRAS_COMMON.append({"letter":r[0],"name":r[1],"enabled":r[2]=="yes","language":r[3],"fixed":r[4],"ver":r[5],"description":r[6]})
for lang,d in PER_LANG.items():
    el=[]
    for r in parse_mach(d.get("machinable_extras","")):
        if len(r)>=7:
            el.append({"letter":r[0],"name":r[1],"enabled":r[2]=="yes","language":r[3],"fixed":r[4],"ver":r[5],"description":r[6]})
    EXTRAS_LANG[lang]=el

ROLES_LANG={}
for lang,d in PER_LANG.items():
    rl=[]
    for r in parse_mach(d.get("machinable_roles","")):
        if len(r)>=5:
            kindpart=r[0]
            kl=kindpart.split("/")[0] if "/" in kindpart else kindpart
            kn=kindpart.split("/")[1] if "/" in kindpart else ""
            rl.append({"kind_letter":kl,"kind_name":kn,"name":r[1],"enabled":r[2]=="on","ver":r[3],"description":r[4]})
    ROLES_LANG[lang]=rl

PARSER_VERSION={}
for lang,d in PER_LANG.items():
    m=re.search(r":\s*([0-9]+\.[0-9]+)", d.get("version",""))
    PARSER_VERSION[lang]=m.group(1) if m else "0.0"

def section_list(text, header):
    out=[]
    active=False
    for line in (text or "").splitlines():
        if line.strip()==header:
            active=True; continue
        if active:
            if line.strip(): out.append(line.strip())
            # stop at next header? lists only one section, fine
    return out

MAP_EXT={}
MAP_PAT={}
MAP_REXPR={}
ALIASES={}
for lang,d in PER_LANG.items():
    MAP_EXT[lang]=section_list(d.get("map_extensions",""), "#EXTENSION")
    MAP_PAT[lang]=section_list(d.get("map_patterns",""), "#PATTERN")
    # rexprs
    rx=[]
    txt=d.get("map_rexprs","")
    lines=txt.splitlines()
