# ---------- Output formatting ----------
def escape_pattern_text(s):
    s=s.replace("\\", "\\\\").replace("/", "\\/").replace("\t", "\\t").replace("\r", "\\r")
    return s

def make_pattern(tag, opts):
    if tag.kind_letter=="F" and tag.language=="NONE":
        return None
    txt = tag.pattern_text if tag.pattern_text is not None else tag.line_text
    esc = escape_pattern_text(txt)
    limit=opts.pattern_length_limit
    if limit and len(esc) > limit:
        esc_trunc=esc[:limit]
        return f"/^{esc_trunc}/"
    suffix=""
    if tag.line_has_newline and not tag.pattern_no_end:
        suffix="$"
    # If pattern_text is custom and shorter than line, original usually suppresses $
    if tag.pattern_text is not None and tag.pattern_no_end:
        suffix=""
    return f"/^{esc}{suffix}/"

def make_excmd(tag, opts):
    if tag.kind_letter=="F" and tag.language=="NONE":
        return "1"
    if opts.excmd=="number":
        return str(tag.line_no)
    elif opts.excmd=="pattern":
        return make_pattern(tag, opts) or str(tag.line_no)
    elif opts.excmd=="combine":
        return f"{tag.line_no};{make_pattern(tag, opts) or ''}"
    else: # mix
        return make_pattern(tag, opts) or str(tag.line_no)

def tag_extras_names(tag, opts):
    names=[]
    # derived from attributes
    if tag.file_scope: names.append("fileScope")
    if tag.anonymous: names.append("anonymous")
    if tag.ref: names.append("reference")
    # custom extras_list may contain names
    for n in tag.extras_list:
        if n not in names: names.append(n)
    return names

def common_custom_fields(tag, opts):
    # returns list of (name, value) for custom fields that are enabled
    out=[]
    for k,v in tag.custom.items():
        # determine if field is enabled: if it's a common named field, check letter mapping; else lang field
        # common named fields handled elsewhere (signature/access etc are attrs, not custom)
        enabled=True
        # language specific
        if tag.language in opts.fields_lang and k in opts.fields_lang[tag.language]:
            enabled=opts.fields_lang[tag.language][k]
        elif tag.language in opts.custom_langs and k in opts.custom_langs[tag.language].get("fields",{}):
            enabled=opts.custom_langs[tag.language]["fields"][k].get("enabled", True)
        else:
            # if field is known for lang but disabled, respect; if unknown, show if ... default yes for fields with letter '-' enabled yes captured; we already checked.
            # search fields_lang for disabled entry
            for f in FIELDS_LANG.get(tag.language,[]):
                if f["name"]==k: enabled=f["enabled"]; break
        if enabled:
