    elif f.get("k"):
        kind_value=tag.kind_letter
    if kind_value is not None: fields.append(kind_value)
    if f.get("n"): fields.append(f"line:{tag.line_no}")
    if f.get("l"): fields.append(f"language:{tag.language}")
    if tag.scope_name and (f.get("s") or f.get("Z")):
        if f.get("Z"): fields.append(f"scope:{tag.scope_kind}:{tag.scope_name}")
        else: fields.append(f"{tag.scope_kind}:{tag.scope_name}")
    if tag.typeref and f.get("t"): fields.append(f"typeref:{tag.typeref}")
    if tag.file_scope and f.get("f"): fields.append("file:")
    if (tag.has_inherits or tag.inherits) and f.get("i"): fields.append(f"inherits:{tag.inherits}")
    if tag.access and f.get("a"): fields.append(f"access:{tag.access}")
    if tag.signature and f.get("S"): fields.append(f"signature:{tag.signature}")
    if tag.custom.get("implementation") and f.get("m"): fields.append(f"implementation:{tag.custom.pop('implementation') if False else tag.custom.get('implementation')}")
