    if tag.typeref and f.get("t"): obj["typeref"]=tag.typeref
    if f.get("K") or f.get("k") or f.get("z"): obj["kind"]=tag.kind_name
    if (tag.has_inherits or tag.inherits) and f.get("i"): obj["inherits"]=tag.inherits if tag.inherits else False
    if tag.access and f.get("a"): obj["access"]=tag.access
    if tag.signature and f.get("S"): obj["signature"]=tag.signature
    if tag.scope_name and (f.get("s") or f.get("Z") or f.get("p")):
        obj["scope"]=tag.scope_name; obj["scopeKind"]=tag.scope_kind
    if f.get("r"): obj["roles"]=tag.roles or "def"
    if f.get("E"):
        ex=tag_extras_names(tag, opts)
        if ex: obj["extras"]=",".join(ex)
    for k,v in common_custom_fields(tag, opts):
        if k=="implementation" and f.get("m"):
            obj["implementation"]=v; continue
        obj[k]=v
    if tag.end is not None and f.get("e"): obj["end"]=tag.end
    if tag.nth is not None and f.get("o"): obj["nth"]=tag.nth
    if tag.epoch is not None and f.get("T"): obj["epoch"]=tag.epoch
    return json.dumps(obj, ensure_ascii=False, separators=(", ", ": "))

def compact_line(s):
    return s.strip()

def format_xref_value(tag, opts, letter, width, left_align):
    # returns string value for field letter
    f=opts.fields_common
    if letter=="N": v=tag.name
    elif letter=="F": v=tag.path
    elif letter=="K": v=tag.kind_name
    elif letter=="k": v=tag.kind_letter
    elif letter=="n": v=str(tag.line_no)
    elif letter=="C": v=compact_line(tag.pattern_text if tag.pattern_text is not None else tag.line_text)
    elif letter=="P": v=make_pattern(tag, opts) or ""
    elif letter=="l": v=tag.language
    elif letter=="s": v=tag.scope_name
    elif letter=="p": v=tag.scope_kind
    elif letter=="S": v=tag.signature or ""
    elif letter=="a": v=tag.access or ""
    elif letter=="t": v=tag.typeref or ""
    elif letter=="e": v=str(tag.end) if tag.end is not None else ""
    elif letter=="f": v="file:" if tag.file_scope else ""
    else:
        # custom by name? single letter unknown
        v=""
    if width:
        try:
            w=int(width)
        except: w=0
        if w:
            if left_align: v=v.ljust(w)
            else: v=v.rjust(w)
    return v

def format_tag_xref(tag, opts):
    fmt=opts.xformat or "%-16N %-10K %4n %-16F %C"
    out=[]; i=0
    while i<len(fmt):
        if fmt[i]=="%" and i+1<len(fmt):
            j=i+1
            left=False
            if j<len(fmt) and fmt[j]=="-": left=True; j+=1
            width=""
            while j<len(fmt) and fmt[j].isdigit(): width+=fmt[j]; j+=1
            if j>=len(fmt): break
            letter=fmt[j]
            if letter=="%": out.append("%")
            else: out.append(format_xref_value(tag, opts, letter, width, left))
            i=j+1
        else:
            out.append(fmt[i]); i+=1
    return "".join(out)

def format_tag(tag, opts):
    if opts.output_format=="json": return format_tag_json(tag, opts)
    if opts.output_format=="xref": return format_tag_xref(tag, opts)
    if opts.output_format=="etags": return ""  # handled separately
    return format_tag_u(tag, opts)  # u-ctags and e-ctags same

