        return f"{header}\t{p.path}\t/{escape_desc(p.pattern)}/"

def sort_lines(lines, opts):
    if opts.sort=="no" or not lines:
        return lines
    # Use external sort to mimic GNU sort -u / -f -u if available
    try:
        args=["sort","-u"]
        if opts.sort=="foldcase": args.append("-f")
        # Ensure byte-wise? Original invokes sort without LC override; inherit env, but set ??? Keep env as is, but add LC_ALL? Original process inherits.
        result=subprocess.run(args, input="\n".join(lines)+"\n", capture_output=True, text=True)
        if result.returncode==0:
            out=result.stdout.splitlines()
            return out
    except Exception:
        pass
    if opts.sort=="foldcase":
        seen=set(); uniq=[]
        for l in lines:
            k=l.lower()
            if k not in seen: seen.add(k); uniq.append(l)
        return sorted(uniq, key=lambda x: x.lower())
    else:
        return sorted(set(lines))

