def parser_for(*langs):
    def deco(fn):
        for l in langs: PARSERS[l]=fn
        return fn
    return deco

def lines_of(ctx):
    return [lt for lt,_ in ctx.lines]

def extract_paren(text_lines, start_line_idx, start_col):
    # return (content_inside, end_line_idx) scanning from '(' at col in line (0-indexed lines)
    depth=0; started=False; content=[]
    in_str=None; esc=False; triple=False
    i=start_line_idx
    col=start_col
    while i < len(text_lines):
        line=text_lines[i]
        j=col
        while j < len(line):
            c=line[j]
            if in_str:
                if triple:
                    if line[j:j+3]==in_str*3:
                        content.append(line[j:j+3]); j+=3; in_str=None; triple=False; continue
                    else:
                        content.append(c); j+=1; continue
                else:
                    content.append(c)
                    if esc: esc=False
                    elif c=="\\": esc=True
                    elif c==in_str: in_str=None
                    j+=1; continue
            else:
                if c in ("'",'"'):
                    # check triple
                    if line[j:j+3]==c*3:
                        in_str=c; triple=True; content.append(line[j:j+3]); j+=3; continue
                    else:
                        in_str=c; content.append(c); j+=1; continue
                if c=="(":
                    depth+=1
                    if depth==1 and not started:
                        started=True; j+=1; continue
                if c==")":
                    depth-=1
                    if depth==0:
                        return "".join(content), i
                if started:
                    content.append(c)
                j+=1
        if started and depth>=1:
            content.append("\n")
        i+=1; col=0
    return "".join(content), i-1

