    def parse_declarators(self, scope, type_desc=None, is_typedef=False, is_static=False, is_extern=False, decl_start_line=1, pre_agg=False):
        # Find declaration scope tokens from self.pos (includes specifiers etc)
        start=self.pos
        # Heuristics for rejection in function scope: statements that are expressions
        # Determine statement end and function candidate
        # Scan ahead
