        # If type_desc agg and seg_idx>=0, seg may be just name (post-agg)
        candidates=[]
        for i,tok in enumerate(seg):
            if tok.kind!="id": continue
            nxt=seg[i+1] if i+1<len(seg) else None
            if nxt is None or nxt.text in ("=","[","{"):
                candidates.append(i)
            elif nxt.text=="(" and seg_idx>0:
                candidates.append(i)
        if candidates:
            # choose last candidate? For `int a` candidate a (end). For `unsigned long counter`, counter end.
            # For segment2 `*b`, candidate b.
            idx=candidates[-1]
            return seg[idx], idx, ""
        # If seg ends with identifier and there is at least one token before, that id is name
        if seg and seg[-1].kind=="id":
            # but if seg is a single id and type_desc agg (typedef struct {} Name;) that's name
            if len(seg)==1 and type_desc and type_desc[0]=="agg":
                return seg[-1], len(seg)-1, ""
            if len(seg)>=2:
                return seg[-1], len(seg)-1, ""
        return None, 0, ""
    def handle_function(self, scope, start, func_candidate, brace_idx, semi_idx, type_desc, is_typedef, is_static, is_extern):
        open_idx, close_idx=func_candidate
        tokens=self.tokens
        # declarator name token is before open, but may be :: qualified or operator or destructor
        name_idx=open_idx-1
