        rt_clean=[t for t in return_type_tokens if t.text not in ("typedef","static","extern","inline","virtual","friend","constexpr","explicit","mutable")]
        # agg type?
        if type_desc and type_desc[0]=="agg":
            agg_info=type_desc[1]
            typeref=f"{agg_info['kw']}:{agg_info['qname']}"
        else:
            # pointer stars before name but after return type? rt may include * at end (first_part logic includes? parts start at name, so * before name is in rt_clean last token)
            if rt_clean:
