        is_body=brace_idx is not None
        term_line=tokens[brace_idx].line if is_body else (tokens[semi_idx].line if semi_idx is not None else tokens[close_idx].line)
        # Determine scope for tag and function qname
        func_qname=func_name
        scope_kind_for_tag=""; scope_name_for_tag=""
        file_scope=is_static
        access=""
        if scope.kindcat in ("aggregate","class"):
            # method inside class/struct definition
            if not is_body:
