                # skip declaration
                self.pos=(semi_idx+1) if semi_idx is not None else close_idx+1
                return True
            scope_kind_for_tag=scope.kindname; scope_name_for_tag=scope.qname
            access=scope.current_access or "public"; file_scope=True
            func_qname=scope.qname+"::"+func_name
        elif len(qualified_parts)>1:
            prefix="::".join(qualified_parts[:-1])
            # determine prefix kind: lookup known
            kind_guess=self.known_types.get(prefix, "") or self.known_types.get(qualified_parts[-2],"")
            if kind_guess in ("class","struct","union"): scope_kind_for_tag=kind_guess
            elif kind_guess: scope_kind_for_tag=kind_guess
            else:
                scope_kind_for_tag="class" if qualified_parts[-2][:1].isupper() else "namespace"
            scope_name_for_tag=prefix
