def strip_c_comments_strings(text):
    out=[]; i=0; n=len(text); state=None; # None, linecomment, blockcomment, str, char
    while i<n:
        c=text[i]; nxt=text[i+1] if i+1<n else ""
        if state is None:
            if c=="/" and nxt=="*": state="block"; out.append("  "); i+=2; continue
            if c=="/" and nxt=="/": state="line"; out.append("  "); i+=2; continue
            if c=='"': state="str"; out.append('""'); i+=1; continue
            if c=="'": state="char"; out.append("''"); i+=1; continue
            out.append(c); i+=1; continue
        elif state=="line":
            if c=="\n": state=None; out.append(c)
            else: out.append(" ")
            i+=1; continue
        elif state=="block":
            if c=="*" and nxt=="/": state=None; out.append("  "); i+=2; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
        elif state in ("str","char"):
            quote='"' if state=="str" else "'"
            if c=="\\":
                out.append("  " if nxt!="\n" else " \n"); i+=2; continue
            if c==quote: state=None; out.append("  "); i+=1; continue
            if c=="\n": state=None; out.append(c); i+=1; continue
            out.append(" "); i+=1; continue
    return "".join(out)

