        if self.kindcat in ("aggregate","class"):
            return self.kindname, self.qname
        if self.kindcat=="namespace": return "namespace", self.qname
        if self.kindcat=="function": return "function", self.qname
        return "", ""

def join_c_tokens(tokens):
    # tokens: list of strings
    out=""
    for tok in tokens:
        if not out: out=tok; continue
        if tok in (",",")","]","::",".",">",";"): out+=tok; continue
        prev=out[-1]
        if out.endswith(("(","[","::",".","<")): out+=tok; continue
        if tok=="(": 
            # function pointer paren after type: "int (" -> "int (" keep space for (*) case, but for template?
            out+=" "+tok; continue
        if tok=="<": out+=tok; continue
        if tok=="*":
            if out.endswith("*"): out+=tok
            else: out+=" "+tok
            continue
        # identifier etc
        out+=" "+tok
    return out.strip()

def signature_from_tokens(tokens):
    # join with space rules approximating ctags: remove space after comma, add spaces elsewhere
    out=""
    for tok in tokens:
        if not out: out=tok; continue
        if tok in (",",")","]"): out+=tok; continue
        if out.endswith(","): out+=tok; continue
        if out.endswith("("): out+=tok; continue
        out+=" "+tok
