                for j in range(i, len(seg)):
                    if seg[j].text=="[": depth+=1; content.append("[")
                    elif seg[j].text=="]": depth-=1; content.append("]"); 
                    else: content.append(seg[j].text)
                    if depth==0: break
                # join content as raw tokens without spaces inside?
                return "".join(content)  # content may need join: numbers as is, identifiers
            if seg[i].text=="=": break
        return ""
    def extract_declarator(self, seg, type_desc, seg_idx):
        # returns (name_token, index_in_seg, extra)
        # function pointer: ( * name )
        for i,tok in enumerate(seg):
            if tok.text=="(" and i+2<len(seg) and seg[i+1].text in ("*","&") and seg[i+2].kind=="id":
                # typeref extra for after close paren: (*)(...)
                # find closing )
                extra=""
                close=None
                for j in range(i+3, len(seg)):
                    if seg[j].text==")": close=j; break
                if close is not None and close+1<len(seg) and seg[close+1].text=="(":
                    # params
                    pclose=None; depth=0
                    for j in range(close+1, len(seg)):
                        if seg[j].text=="(": depth+=1
                        elif seg[j].text==")":
                            depth-=1
                            if depth==0: pclose=j; break
                    if pclose:
                        params=[t.text for t in seg[close+2:pclose]]
                        extra=f"(*)({signature_from_tokens(params)})"
                return seg[i+2], i+2, extra
