            # return type tokens = tokens from start to first part index
            # find index of first qualified part
            first_part_idx=name_idx - (len(parts)-1)*2 if parts else name_idx
            # adjust destructor
            if is_destructor: first_part_idx-=1
            return_type_tokens=tokens[start:first_part_idx]
