                    elif seg[j].text=="]": depth-=1; content.append("]"); 
                    else: content.append(seg[j].text)
                    if depth==0: break
                # join content as raw tokens without spaces inside?
                return "".join(content)  # content may need join: numbers as is, identifiers
            if seg[i].text=="=": break
