def apply_header(opts, text, kind=None):
    if not opts.with_list_header and text:
        lines=text.splitlines(True)
        if lines and lines[0].startswith("#"):
            return "".join(lines[1:])
    return text

def patch_mach_enabled(text, opts, lang):
    out=[]
    for line in text.splitlines():
        if line.startswith("#") or not line: out.append(line); continue
        parts=line.split("\t")
        if len(parts)>=3:
            letter=parts[0]; parts[2]="yes" if opts.kind_enabled(lang,letter) else "no"; line="\t".join(parts)
        out.append(line)
    return "\n".join(out)+("\n" if out else "")

def patch_plain_enabled(text, opts, lang):
    # header ENABLED column start
    lines=text.splitlines()
    if not lines: return text
    hdr=lines[0]; col=hdr.find("ENABLED")
    if col==-1: return text
    out=[hdr]
    for line in lines[1:]:
        if not line: out.append(line); continue
        letter=line.split()[0] if line.split() else ""
        val="yes" if opts.kind_enabled(lang,letter) else "no"
        # replace column segment until next column (REFONLY at ...)
        # ENABLED width until next header token
        # find next token pos
        rest=hdr[col:]
        toks=rest.split()
        width=len(rest)  # fallback
        # compute width from header: distance to REFONLY
        ncol=hdr.find("REFONLY", col)
        if ncol!=-1: width=ncol-col
        if len(line)>=col:
            line=line[:col]+val.ljust(width)+line[col+width:] if len(line)>=col+width else line[:col]+val
        out.append(line)
    return "\n".join(out)+"\n"

def filter_roles_text(text, kindspec, machinable):
    if kindspec=="*": return text
    # kindspec can be {name} or letter or name
    want=kindspec.strip("{}")
    lines=text.splitlines(True)
    if not lines: return text
    out=[]
    if lines[0].startswith("#"): out.append(lines[0]); lines=lines[1:]
    for line in lines:
        if machinable:
            parts=line.split("\t"); kindpart=parts[0] if parts else ""
        else:
            parts=line.split(); kindpart=parts[0] if parts else ""
        letter=kindpart.split("/")[0] if "/" in kindpart else kindpart
        name=kindpart.split("/")[1] if "/" in kindpart else ""
        if want==letter or want==name: out.append(line)
    return "".join(out)

def synth_describe(lang, opts):
    ck=opts.custom_langs.get(lang,{})
    lines=[f"About {lang} language","="*55,"enabled: yes",f"version: {ck.get('version','0.0')}","","Mappings/rexprs","-"*55,"","","Mappings/patterns","-"*55,"","","Mappings/extensions","-"*55]
    exts=opts.eff_ext.get(lang,[]); pats=opts.eff_pat.get(lang,[])
    lines.append(" "+" ".join([f"*.{e}" for e in exts]+pats) if exts or pats else "")
    lines+=["","Aliases","-"*55,"#ALIAS","","Kinds","-"*55,"#LETTER NAME      ENABLED REFONLY NROLES MASTER VER DESCRIPTION"]
    for letter,k in ck.get("kinds",{}).items(): lines.append(f"{letter} {k['name']} yes")
    lines+=["","Roles","-"*55,"","Fields","-"*55,"","Extras","-"*55,"","Parameters","-"*55,"","Sub parsers stacked on this parser","-"*55,"","Implementation specific status","-"*55,"allow null tags: no"]
    return "\n".join(lines)+"\n"

def load_option_file(path, opts, maybe=False):
    # returns False if fatal
    if path=="NONE":
        if not opts.quiet: eprint(f"{PROG}: Notice: No options will be read from files or environment")
        opts._options_none=True
        return True
    if not os.path.exists(path):
        if maybe: return True
        err(f'cannot stat "{path}" : No such file or directory'); raise FatalError(1)
    files=[]
    if os.path.isdir(path):
        try:
            entries=sorted(os.listdir(path))
        except Exception as e:
            err(f'cannot stat "{path}" : {e.strerror if hasattr(e,"strerror") else e}'); raise FatalError(1)
        for name in entries:
            if name.endswith(".ctags"): files.append(os.path.join(path,name))
    else:
        files=[path]
    for fp in files:
        try:
            with open(fp,"r",errors="replace") as f: lines=f.readlines()
        except Exception as e:
            if maybe: continue
            err(f'cannot stat "{fp}" : No such file or directory'); raise FatalError(1)
        toks=[]
        for line in lines:
            s=line.strip()
            if not s or s.startswith("#"): continue
            toks.append(s)
        process_token_list(toks, opts, in_config=True)
    return True

def process_config_files(opts):
    if any(t=="--options=NONE" for t in sys.argv[1:]):
        return
    dirs=[]
    xdg=os.environ.get("XDG_CONFIG_HOME")
    home=os.environ.get("HOME","")
    if xdg:
        dirs.append(os.path.join(xdg,"ctags"))
    elif home:
        dirs.append(os.path.join(home,".config","ctags"))
    if home: dirs.append(os.path.join(home,".ctags.d"))
    dirs.append(os.path.join(os.getcwd(),".ctags.d"))
    for d in dirs:
        if os.path.isdir(d):
            for name in sorted(os.listdir(d)):
                if name.endswith(".ctags"):
                    try:
                        with open(os.path.join(d,name)) as f: lines=f.readlines()
                    except: continue
                    toks=[]
                    for line in lines:
                        s=line.strip()
                        if not s or s.startswith("#"): continue
                        toks.append(s)
                    try: process_token_list(toks, opts, in_config=True)
                    except Terminal: raise
                    except FatalError: raise

def error_unknown_option(display):
    err(f"Unknown option: {display}"); raise FatalError(1)

def check_after_file(opts, display):
    if opts.opt_seen_file:
        err(f"{display} option may not follow a file name"); raise FatalError(1)

def process_token_list(tokens, opts, in_config=False):
    idx=0
    while idx<len(tokens):
        tok=tokens[idx]
        # files handling (in cmdline only; config tokens that are files? treat as file if not option)
        if not tok.startswith("-") or tok=="":
            if not in_config:
                opts.opt_seen_file=True; opts.files.append(tok)
            else:
                # config may contain filenames? ignore
                pass
            idx+=1; continue
        # token is option
        display_for_after=None
        if tok.startswith("--"):
            name_eq=tok[2:].split("=",1)[0]; display_for_after=f"--{name_eq}"
        else:
            display_for_after=f"-{tok[1:2]}" if len(tok)>1 else tok
        if not in_config:
            check_after_file(opts, display_for_after)
        # process long
        if tok.startswith("--"):
            idx=handle_long(tokens, idx, opts, in_config)
        elif tok=="-" or tok=="--":
            error_unknown_option(tok)
        else:
            idx=handle_short(tokens, idx, opts, in_config)
    return

def consume_short_arg(tokens, idx, pos_in_tok, token):
    # pos_in_tok: index in token after option char, remaining string is arg if any
    rest=token[pos_in_tok:]
    if rest:
        return rest, idx
    if idx+1<len(tokens):
        return tokens[idx+1], idx+1
    return "", idx

def handle_short(tokens, idx, opts, in_config):
    token=tokens[idx]
    i=1
    while i<len(token):
        ch=token[i]
        # options with args
        if ch in ("f","o","L","I","D","h"):
            arg, new_idx=consume_short_arg(tokens, idx, i+1, token)
            # arg consumption
            if ch in ("f","o"):
                if opts.tagfile is not None and getattr(opts,"_tagfile_set",False):
                    warn("-f option specified more than once, last value used")
                opts.tagfile=arg; opts._tagfile_set=True
            elif ch=="L":
                # load list file now
                load_list_file(arg, opts)
            elif ch=="I":
                opts.ignore_tokens.append(arg)
            elif ch=="D":
                opts.defines.append(arg)
            elif ch=="h":
                opts.includes_h=arg
            return new_idx+1 if new_idx!=idx else idx+1
        elif ch=="R": opts.recurse=True
        elif ch=="a": opts.append=True
        elif ch=="e": opts.output_format="etags"
        elif ch=="x": opts.output_format="xref"
        elif ch=="u": opts.sort="no"
        elif ch=="n": opts.excmd="number"
        elif ch=="N": opts.excmd="pattern"
        elif ch=="V": opts.verbose=True
        elif ch=="G": opts.guess_eagerly=True
        elif ch=="B": opts.pattern_backward=True
        elif ch=="F": opts.pattern_backward=False
        elif ch=="?":
            output_and_exit(GLOBALS.get("help", VERSION_TEXT))
        else:
            error_unknown_option(f"-{ch}")
        i+=1
    return idx+1

def load_list_file(arg, opts):
    if arg=="-":
        names=sys.stdin.read().splitlines()
        for n in names:
            n=n.strip()
            if n: opts.files.append(n); opts.opt_seen_file=True
        return
    if not os.path.exists(arg):
        err(f'cannot open list file "{arg}" : No such file or directory'); raise FatalError(1)
    try:
        with open(arg) as f: names=f.readlines()
    except Exception as e:
        err(f'cannot open list file "{arg}" : No such file or directory'); raise FatalError(1)
    for n in names:
        n=n.strip()
        if n: opts.files.append(n); opts.opt_seen_file=True

