def handle_languages(value, opts, idx):
    opts._languages_modified=True
    spec=value or ""
    mode="set"; body=spec
    if body.startswith("+"): mode="add"; body=body[1:]
    elif body.startswith("-"): mode="remove"; body=body[1:]
    items=[x.strip() for x in body.split(",") if x.strip()!=""] if body else []
    # warnings per original quirks
    contains_all=any(x.lower()=="all" for x in items)
    if mode=="set" or contains_all:
        warn("Enabling Cargo subparser may enable TOML parser."); warn("The current implementation of the TOML parser is broken.")
    else:
        # plus mode
        lowered=[x.lower() for x in items]
        if any(canon_lang(x)=="TOML" for x in items): warn("The current implementation of the TOML parser is broken.")
        elif any(canon_lang(x)=="Cargo" for x in items): warn("Enabling Cargo subparser may enable TOML parser.")
    if mode=="set":
        newset=set()
        for it in items:
            if it.lower()=="all": newset=set(LANG_ORDER)
            else:
                lang=canon_lang(it)
                if lang: newset.add(lang)
                elif it in opts.custom_langs: newset.add(it)
                else: warn(f'Unknown language "{it}" in "languages" option')
        opts.languages_enabled=newset
    elif mode=="add":
        for it in items:
            if it.lower()=="all": opts.languages_enabled.update(LANG_ORDER)
            else:
                lang=canon_lang(it)
                if lang: opts.languages_enabled.add(lang)
                elif it in opts.custom_langs: opts.languages_enabled.add(it)
                else: warn(f'Unknown language "{it}" in "languages" option')
    else: # remove
        for it in items:
            if it.lower()=="all": opts.languages_enabled=set()
            else:
                lang=canon_lang(it)
                if lang: opts.languages_enabled.discard(lang)
                elif it in opts.custom_langs: opts.languages_enabled.discard(it)
                else: warn(f'Unknown language "{it}" in "languages" option')
    return idx+1

def handle_langmap(value, opts, idx):
    if not value: return idx+1
    # format entries separated by ',' but extensions list within: lang:[+|-]exts, ...
    # Parse by commas but langmap entries contain ':'; extensions sequences are dot/pattern series concatenated, ambiguity.
    # Approach: split by ',' into entries; each "lang:map" where map may continue... Original examples single entry.
    entries=value.split(",")
    for entry in entries:
        if ":" not in entry:
            warn(f'Unknown language "{entry}" in "langmap" option'); continue
        lang_in, mapspec=entry.split(":",1)
        lang=canon_lang(lang_in)
        if lang is None:
            warn(f'Unknown language "{lang_in}" in "langmap" option'); continue
        mode="set"
        if mapspec.startswith("+"): mode="add"; mapspec=mapspec[1:]
        elif mapspec.startswith("-"): mode="remove"; mapspec=mapspec[1:]
        # parse tokens: extensions start with '.' and continue until next '.' or pattern start '(' '[' or '*'
        exts=[]; pats=[]
        i=0
        while i<len(mapspec):
            if mapspec[i]==".":
                j=i+1
                while j<len(mapspec) and mapspec[j] not in ".([*": j+=1
                exts.append(mapspec[i+1:j]); i=j
            elif mapspec[i]=="(":
                j=mapspec.find(")",i)
                if j==-1: pats.append(mapspec[i:]); break
                pats.append(mapspec[i:j+1]); i=j+1
            elif mapspec[i]=="[":
                # pattern like [Mm]akefile then following letters
                j=i
                # consume bracket then following word chars until '.' or '(' etc
                depth=0
                while j<len(mapspec):
                    if mapspec[j]=="[": depth+=1
                    elif mapspec[j]=="]": depth-=1
                    elif depth==0 and mapspec[j] in ".(": break
                    j+=1
                pats.append(mapspec[i:j]); i=j
            elif mapspec[i]=="*":
                j=i+1
                while j<len(mapspec) and mapspec[j] not in ".(": j+=1
                pats.append(mapspec[i:j]); i=j
            else:
                # bare pattern word until '.'/'('
                j=i
                while j<len(mapspec) and mapspec[j] not in ".(": j+=1
                pats.append(mapspec[i:j]); i=j
        if mode=="set":
            if exts: opts.eff_ext[lang]=exts
            elif pats and not exts: opts.eff_ext[lang]=[]
            if pats: opts.eff_pat[lang]=pats
            elif exts: opts.eff_pat[lang]=[]
        elif mode=="add":
            for e in exts:
                if e not in opts.eff_ext[lang]: opts.eff_ext[lang].append(e)
            for p in pats:
                if p not in opts.eff_pat[lang]: opts.eff_pat[lang].append(p)
        else:
            opts.eff_ext[lang]=[e for e in opts.eff_ext[lang] if e not in exts]
            opts.eff_pat[lang]=[p for p in opts.eff_pat[lang] if p not in pats]
    return idx+1

def handle_map_lang(lang_in, value, opts, idx):
    lang=canon_lang(lang_in)
    if lang is None:
        if lang_in in opts.custom_langs: lang=lang_in
        else: warn(f'Unknown language "{lang_in}" in "map-{lang_in}" option'); return idx+1
    spec=value or ""
    mode="set"
    if spec.startswith("+"): mode="add"; spec=spec[1:]
    elif spec.startswith("-"): mode="remove"; spec=spec[1:]
    # determine type: extension if starts with '.'; rexpr if starts with '%' or '('? Format: %...% for regex? In list-maps regex shown %...%
    is_rexpr=False; is_pat=False; ext=None
    if spec.startswith("."):
        ext=spec[1:]
    elif spec.startswith("%"):
        is_rexpr=True; spec=spec.strip("%")
    elif spec.startswith("(") or spec.startswith("[") or spec.startswith("*") or (spec and not spec.startswith(".")):
        # could be pattern or rexpr if contains \\ or $ etc. Original map accepts <pattern>|<rexpr>: rexpr designated by ??? patterns are glob filename; if contains backslash regex, treat rexpr
        if "\\" in spec or spec.endswith("$"): is_rexpr=True
        else: is_pat=True
    if is_rexpr:
        if mode=="set": opts.eff_rexpr[lang]=[(spec,"sensitive")]
        elif mode=="add": opts.eff_rexpr[lang].append((spec,"sensitive"))
        else: opts.eff_rexpr[lang]=[x for x in opts.eff_rexpr[lang] if x[0]!=spec]
    elif ext is not None:
        if mode=="set": opts.eff_ext[lang]=[ext]
        elif mode=="add":
            if ext not in opts.eff_ext[lang]: opts.eff_ext[lang].append(ext)
        else: opts.eff_ext[lang]=[e for e in opts.eff_ext[lang] if e!=ext]
    elif is_pat:
        if mode=="set": opts.eff_pat[lang]=[spec]
        elif mode=="add":
            if spec not in opts.eff_pat[lang]: opts.eff_pat[lang].append(spec)
        else: opts.eff_pat[lang]=[p for p in opts.eff_pat[lang] if p!=spec]
    return idx+1

def handle_pseudo_tags(value, opts, idx):
    spec=value or ""
    mode="set"; body=spec
    if body.startswith("+"): mode="add"; body=body[1:]
    elif body.startswith("-"): mode="remove"; body=body[1:]
    items=[x.strip() for x in body.split(",") if x.strip()] if body else []
    for it in items:
