def parse_regex_def(value):
    # value like /pattern/name/kind/flags or /pattern/name/{kindspec}/...
    if not value or not value.startswith("/"): return None
    # split by unescaped '/'
    parts=[]; cur=""; esc=False; i=1
    while i<len(value):
        c=value[i]
        if esc: cur+=c; esc=False; i+=1; continue
        if c=="\\": cur+=c; esc=True; i+=1; continue
        if c=="/": parts.append(cur); cur=""; i+=1; continue
        cur+=c; i+=1
    parts.append(cur)
    # parts[0]=pattern, [1]=name pattern, [2]= kind spec, [3]=flags optional
    if len(parts)<3: return None
    return parts

def handle_regex_def(lang_in, value, opts, idx, multiline=False):
    lang=canon_lang(lang_in)
    is_custom=False
    if lang is None:
        if lang_in in opts.custom_langs: lang=lang_in; is_custom=True
        else: warn(f'Unknown language "{lang_in}" in "regex-{lang_in}" option'); return idx+1
    parts=parse_regex_def(value or "")
    if parts is None: return idx+1
    pattern, namepat, kindspec = parts[0], parts[1], parts[2]
    flags=parts[3] if len(parts)>3 else ""
    # kindspec format: letter,name,description or {letter,name,...}?
    kindspec=kindspec.strip()
    letter=None; kname=None
    # kindspec could be like 'c,class,classes' for regex? In ctags regex defs, kind spec is one letter optionally?
    # Tests examples usually: /\1/f,function/ ??? Actually documentation: /line_pattern/name_pattern/kind-spec/[flags] where kind-spec is letter or {letter,name}
    # We'll interpret: if starts '{' inside? parts split already? kindspec could be 'f' or 'f,function' ?
    if "," in kindspec:
        ks=kindspec.split(","); letter=ks[0].strip("{} "); kname=ks[1] if len(ks)>1 else ""
    else: letter=kindspec.strip("{} ")
    # Resolve letter to kind name for filtering
    if lang in opts.custom_langs and letter in opts.custom_langs[lang].get("kinds",{}): kname=opts.custom_langs[lang]["kinds"][letter]["name"]
    elif KINDS.get(lang,{}).get(letter): kname=KINDS[lang][letter]["name"]
    entry={"pattern":pattern,"name":namepat,"letter":letter,"kindname":kname,"flags":flags,"multiline":multiline}
    if lang not in opts.custom_langs:
        opts.custom_langs[lang]={"kinds":{},"kinds_by_name":{},"kinds_enabled":{},"regex":[],"mline":[],"fields":{},"extras":{},"version":PARSER_VERSION.get(lang,"0.0"),"shadow":True}
    opts.custom_langs[lang]["regex" if not multiline else "mline"].append(entry)
    # Ensure language enabled; regex for builtin language adds to its parsing (handled in parse dispatch)
    return idx+1

