def parse_regex_def(value):
    # value like /pattern/name/kind/flags or /pattern/name/{kindspec}/...
    if not value or not value.startswith("/"): return None
    # split by unescaped '/'
    parts=[]; cur=""; esc=False; i=1
    while i<len(value):
        c=value[i]
        if esc: cur+=c; esc=False; i+=1; continue
        if c=="\\": cur+=c; esc=True; i+=1; continue
        if c=="/": parts.append(cur); cur=""; i+=1; continue
        cur+=c; i+=1
    parts.append(cur)
    # parts[0]=pattern, [1]=name pattern, [2]= kind spec, [3]=flags optional
    if len(parts)<3: return None
    return parts

def handle_regex_def(lang_in, value, opts, idx, multiline=False):
    lang=canon_lang(lang_in)
