            if c=="/" and nxt=="*": state="block"; out.append("  "); i+=2; continue
            if c=="/" and nxt=="/": state="line"; out.append("  "); i+=2; continue
            if c in ('"',"'","`"): state=c; out.append(c*2); i+=1; continue
            out.append(c); i+=1; continue
        elif state=="line":
            if c=="\n": state=None; out.append(c)
            else: out.append(" ")
            i+=1; continue
        elif state=="block":
            if c=="*" and nxt=="/": state=None; out.append("  "); i+=2; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
        else:
            quote=state
            if c=="\\": out.append("  " if nxt!="\n" else " \n"); i+=2; continue
            if c==quote: state=None; out.append("  "); i+=1; continue
            if c=="\n" and quote!="`": state=None; out.append(c); i+=1; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
