        is_async=False
        if self.cur().text=="async": self.advance(); is_async=True
        if self.cur().text=="function":
            self.advance()
            if self.cur().text=="*": self.advance()
            if self.cur().kind=="id": self.advance()
            sig="()"
            if self.cur().text=="(": 
                oi=self.pos; ci=self.match(oi,"(",")"); sig=self.sig_from_parens(oi,ci); self.pos=ci+1
