                    # Let caller create? We'll tag as function with no scope
                    sk,sn=self.scope_for(entity); tag=self.ctx.tag(last.text, last.line, "f", scope_kind=sk, scope_name=sn)
                else:
                    tag=self.ctx.tag(last.text, last.line, "f", scope_kind="variable", scope_name=".".join(t.text for t in parts[:-1])); 
                tag.signature=sig
            while not self.eof() and self.cur().text not in ("{",";",",","}"): self.advance()
            if self.cur().text=="{":
                # nested scope name based on last
                ent_name=last.text; qn=(self.qname_for(entity, ent_name))
                # For method, qualified may be class etc but nested function scope naming approximated
                ent=JSEntity(ent_name, qn, "function", in_function=True); self.advance(); self.parse_statements(ent, in_function=True)
                if self.cur().text=="}": self.advance()
            if self.cur().text==";": self.advance()
            return True
        # arrow detection
        self.pos=init_save
        arrow_idx=None; depth=0; i=self.pos
        while i<len(self.tokens):
            txt=self.tokens[i].text
            if txt in ("(","[","{"): depth+=1
            elif txt in (")","]","}"):
                if depth==0: break
                depth-=1
            elif txt=="=>" and depth==0: arrow_idx=i; break
            elif txt in (",",";") and depth==0: break
            i+=1
        if arrow_idx is not None:
            tag=self.ctx.tag(last.text, last.line, "f", scope_kind="variable" if len(parts)>1 else self.scope_for(entity)[0], scope_name=".".join(t.text for t in parts[:-1]) if len(parts)>1 else self.scope_for(entity)[1])
            tag.signature="()"
            self.pos=arrow_idx+1
            if self.cur().text=="{":
                ent=JSEntity(last.text, self.qname_for(entity,last.text), "function", in_function=True); self.advance(); self.parse_statements(ent, True)
                if self.cur().text=="}": self.advance()
            else: self.skip_expr_to_comma()
            if self.cur().text==";": self.advance()
            return True
        if self.cur().text=="{" and len(parts)>0 and not self.is_ts:
            # assignment of object to property: tag property ? and parse object
            # e.g., obj.x = { method }
            # We'll create property tag for last
            # But simple `obj = {}` without declaration is variable creation? Not observed; skip creating to avoid false
            self.pos=self.match(self.pos,"{","}")+1
            if self.cur().text==";": self.advance()
            return True
