# ---------- JavaScript / TypeScript parser ----------
JSToken=collections.namedtuple("JSToken", ["text","kind","line","col"])
def strip_js_comments_strings(text):
    out=[]; i=0; n=len(text); state=None
    while i<n:
        c=text[i]; nxt=text[i+1] if i+1<n else ""
        if state is None:
            if c=="/" and nxt=="*": state="block"; out.append("  "); i+=2; continue
            if c=="/" and nxt=="/": state="line"; out.append("  "); i+=2; continue
            if c in ('"',"'","`"): state=c; out.append(c*2); i+=1; continue
            out.append(c); i+=1; continue
        elif state=="line":
            if c=="\n": state=None; out.append(c)
            else: out.append(" ")
            i+=1; continue
        elif state=="block":
            if c=="*" and nxt=="/": state=None; out.append("  "); i+=2; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
        else:
            quote=state
            if c=="\\": out.append("  " if nxt!="\n" else " \n"); i+=2; continue
            if c==quote: state=None; out.append("  "); i+=1; continue
            if c=="\n" and quote!="`": state=None; out.append(c); i+=1; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
    return "".join(out)

class JSEntity:
    def __init__(self, name, qname, scope_kind, in_function=False):
        self.name=name; self.qname=qname; self.scope_kind=scope_kind; self.in_function=in_function

class JSParser:
    def __init__(self, ctx, is_ts=False):
        self.ctx=ctx; self.is_ts=is_ts; self.lang=ctx.language; self.lines=lines_of(ctx)
        text="\n".join(self.lines)
        clean=strip_js_comments_strings(text)
        self.tokens=[]
        for lidx,line in enumerate(clean.split("\n")):
            i=0
            while i<len(line):
                c=line[i]
                if c.isspace(): i+=1; continue
                if c.isalpha() or c in "_$":
                    j=i+1
                    while j<len(line) and (line[j].isalnum() or line[j] in "_$"): j+=1
                    self.tokens.append(JSToken(line[i:j],"id",lidx+1,i)); i=j; continue
                if c.isdigit():
                    j=i+1
                    while j<len(line) and (line[j].isalnum() or line[j] in "._"): j+=1
                    self.tokens.append(JSToken(line[i:j],"num",lidx+1,i)); i=j; continue
                if line[i:i+2] in ('""',"''","``"):
                    self.tokens.append(JSToken(line[i:i+2],"str",lidx+1,i)); i+=2; continue
                if line[i:i+3]=="...": self.tokens.append(JSToken("...","punct",lidx+1,i)); i+=3; continue
                if line[i:i+2] in ("=>","::","->","&&","||","==","!=","<=",">=","++","--","+=","-=","**","?.","??"):
                    self.tokens.append(JSToken(line[i:i+2],"punct",lidx+1,i)); i+=2; continue
                self.tokens.append(JSToken(c,"punct",lidx+1,i)); i+=1
        self.pos=0
    def cur(self, off=0):
        p=self.pos+off
        return self.tokens[p] if 0<=p<len(self.tokens) else JSToken("","eof",0,0)
    def advance(self):
        t=self.cur(); self.pos+=1; return t
    def eof(self): return self.pos>=len(self.tokens)
    def match(self, start, open_t, close_t):
        depth=0; i=start
        while i<len(self.tokens):
            if self.tokens[i].text==open_t: depth+=1
            elif self.tokens[i].text==close_t:
                depth-=1
                if depth==0: return i
            i+=1
        return len(self.tokens)-1
    def qname_for(self, entity, name):
        return (entity.qname+"." if entity else "")+name
    def scope_for(self, entity):
        if entity: return entity.scope_kind, entity.qname
        return "", ""
    def sig_from_parens(self, open_idx, close_idx):
        if open_idx>=len(self.tokens) or close_idx>=len(self.tokens): return "()"
        ot=self.tokens[open_idx]; ct=self.tokens[close_idx]
        if ot.line==ct.line:
            line=self.lines[ot.line-1]
            return line[ot.col:ct.col+1]
        inner=[t.text for t in self.tokens[open_idx+1:close_idx]]
        return "("+", ".join(inner)+")" if inner else "()"
    def parse(self):
        self.parse_statements(None, in_function=False, top=True)
    def parse_statements(self, entity, in_function=False, top=False):
        while not self.eof():
            if self.cur().text=="}": return
            if self.try_parse_statement(entity, in_function):
                continue
            else:
                # generic advance; if block brace, parse inner as statements retaining entity/in_function
                if self.cur().text=="{":
                    self.advance(); self.parse_statements(entity, in_function=in_function)
                    if self.cur().text=="}": self.advance()
                    continue
                self.advance()
    def try_parse_statement(self, entity, in_function):
        t=self.cur()
        # export/import
        if t.text=="export":
            # export default / declarations
            self.advance()
            if self.cur().text=="default": self.advance()
            if self.cur().text in ("function","class","const","let","var","interface","enum","namespace","type","abstract","declare","async"):
                return self.try_parse_statement(entity, in_function)
            # export { } / * ; skip to ;
            self.skip_statement(); return True
        if t.text=="import":
            if self.is_ts and self.cur(1).kind=="id" and self.cur(2).text=="=":
                # alias not tagged (observed)
                self.skip_statement(); return True
            self.skip_statement(); return True
        if t.text=="declare":
            self.advance(); return self.try_parse_statement(entity, in_function)
        if t.text=="abstract" and self.cur(1).text=="class":
            self.advance(); return self.try_parse_statement(entity, in_function)
        if t.text in ("interface",) and self.is_ts:
            return self.parse_interface(entity)
        if t.text in ("enum",) and self.is_ts:
            return self.parse_enum(entity)
        if t.text in ("namespace","module") and self.is_ts:
