        if state is None:
            if c=="/" and nxt=="*": state="block"; out.append("  "); i+=2; continue
            if c=="/" and nxt=="/": state="line"; out.append("  "); i+=2; continue
            if c in ('"',"'","`"): state=c; out.append(c*2); i+=1; continue
            out.append(c); i+=1; continue
        elif state=="line":
            if c=="\n": state=None; out.append(c)
            else: out.append(" ")
