# ---------- Rust parser ----------
def strip_rust(text):
    out=[]; i=0; n=len(text); state=None
    while i<n:
        c=text[i]; nxt=text[i+1] if i+1<n else ""
        if state is None:
            if c=="/" and nxt=="*": state="block"; out.append("  "); i+=2; continue
            if c=="/" and nxt=="/": state="line"; out.append("  "); i+=2; continue
            if c=='"': state='"'; out.append('""'); i+=1; continue
            if c=="'":
                # char literal if pattern 'x' or '\n' etc, lifetime if 'ident not followed by '
                if i+2<n and text[i+2]=="'": state="'"; out.append("''"); i+=1; continue
                if nxt=="\\" : state="'"; out.append("''"); i+=1; continue
                out.append(c); i+=1; continue
            if c=="`": state="`"; out.append("``"); i+=1; continue
            out.append(c); i+=1; continue
        elif state=="line":
            if c=="\n": state=None; out.append(c)
            else: out.append(" ")
            i+=1; continue
        elif state=="block":
            if c=="*" and nxt=="/": state=None; out.append("  "); i+=2; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
        else:
            q=state
            if c=="\\": out.append("  " if nxt!="\n" else " \n"); i+=2; continue
            if c==q: state=None; out.append("  "); i+=1; continue
            out.append("\n" if c=="\n" else " "); i+=1; continue
    return "".join(out)

class RustEntity:
    def __init__(self, name, path, scope_kind):
        self.name=name; self.path=path; self.scope_kind=scope_kind

class RustParser:
    def __init__(self, ctx):
        self.ctx=ctx; self.lines=lines_of(ctx)
        clean=strip_rust("\n".join(self.lines))
        self.tokens=[]
        for lidx,line in enumerate(clean.split("\n")):
            i=0
            while i<len(line):
                c=line[i]
                if c.isspace(): i+=1; continue
                if c=="'" and i+1<len(line) and (line[i+1].isalpha() or line[i+1]=="_"):
                    j=i+2
                    while j<len(line) and (line[j].isalnum() or line[j]=="_"): j+=1
                    self.tokens.append(JSToken(line[i:j],"life",lidx+1,i)); i=j; continue
                if c.isalpha() or c=="_":
                    j=i+1
                    while j<len(line) and (line[j].isalnum() or line[j]=="_"): j+=1
                    self.tokens.append(JSToken(line[i:j],"id",lidx+1,i)); i=j; continue
                if c.isdigit():
                    j=i+1
                    while j<len(line) and (line[j].isalnum() or line[j] in "._"): j+=1
                    self.tokens.append(JSToken(line[i:j],"num",lidx+1,i)); i=j; continue
                if line[i:i+2] in ('""',"''"):
                    self.tokens.append(JSToken(line[i:i+2],"str",lidx+1,i)); i+=2; continue
                if line[i:i+2] in ("::","->","=>","&&","||","==","!=","<=",">=",".."):
                    self.tokens.append(JSToken(line[i:i+2],"punct",lidx+1,i)); i+=2; continue
                self.tokens.append(JSToken(c,"punct",lidx+1,i)); i+=1
        self.pos=0
    def cur(self,off=0):
        p=self.pos+off; return self.tokens[p] if 0<=p<len(self.tokens) else JSToken("","eof",0,0)
    def advance(self):
        t=self.cur(); self.pos+=1; return t
    def eof(self): return self.pos>=len(self.tokens)
    def match(self,start,o,c):
        d=0; i=start
        while i<len(self.tokens):
            if self.tokens[i].text==o: d+=1
            elif self.tokens[i].text==c:
                d-=1
                if d==0: return i
            i+=1
        return len(self.tokens)-1
    def match_angle(self,start):
        d=0; i=start
        while i<len(self.tokens):
            tx=self.tokens[i].text
            if tx=="<": d+=1
            elif tx==">": d-=1
            elif tx==">>": d-=2
            if d<=0: return i
            i+=1
        return i
    def scope(self, ent):
        if not ent: return "",""
        return ent.scope_kind, ent.path
    def join_path(self, ent, name):
        if ent and ent.scope_kind in ("module","function"): return ent.path+"::"+name
        if ent and ent.scope_kind in ("implementation","interface","struct","enum"): return ent.path+"::"+name
        return name
    def sig_from(self, oi, ci, ret_text):
        ot=self.tokens[oi]; ct=self.tokens[ci]
        if ot.line==ct.line: sig=self.lines[ot.line-1][ot.col:ct.col+1]
        else: sig="("+", ".join(t.text for t in self.tokens[oi+1:ci])+")"
        if ret_text: sig+=f" -> {ret_text}"
        return sig
    def parse(self):
        self.parse_items(None)
    def parse_items(self, ent):
        while not self.eof() and self.cur().text!="}":
            if self.cur().text==";": self.advance(); continue
            if self.try_item(ent): continue
            # generic block / expression brace
            if self.cur().text=="{":
                # parse items inside ??? For fn bodies, try_item handles fn and will parse its body with function entity. A bare block in a function: parse items with same ent
                self.advance(); self.parse_items(ent)
                if self.cur().text=="}": self.advance(); continue
            self.advance()
    def consume_modifiers(self):
        while True:
            t=self.cur().text
            if t=="pub":
                self.advance(); 
                if self.cur().text=="(": self.pos=self.match(self.pos,"(",")")+1
                continue
            if t in ("unsafe","async","extern","default","final"):
                self.advance();
                if self.cur().kind=="str": self.advance()
                continue
            break
    def try_item(self, ent):
        # attributes #[...]
        if self.cur().text=="#" and self.cur(1).text=="[":
            self.pos=self.match(self.pos+1,"[","]")+1; return True
        save=self.pos
        self.consume_modifiers()
        t=self.cur()
        if t.text=="fn": return self.parse_fn(ent)
        if t.text=="struct": return self.parse_struct(ent)
        if t.text=="enum": return self.parse_enum(ent)
        if t.text=="trait": return self.parse_trait(ent)
        if t.text=="impl": return self.parse_impl(ent)
        if t.text=="mod": return self.parse_mod(ent)
        if t.text=="const":
            # const fn handled: if next is fn
            if self.cur(1).text=="fn": self.advance(); return self.parse_fn(ent)
            self.advance(); name_tok=self.cur()
            if name_tok.kind=="id":
                self.advance(); sk,sn=self.scope(ent); self.ctx.tag(name_tok.text, name_tok.line, "C", scope_kind=sk, scope_name=sn)
            self.skip_to_semi(); return True
        if t.text=="static":
            self.advance(); 
            if self.cur().text=="mut": self.advance()
            name_tok=self.cur()
            if name_tok.kind=="id": self.advance(); sk,sn=self.scope(ent); self.ctx.tag(name_tok.text, name_tok.line, "v", scope_kind=sk, scope_name=sn)
            self.skip_to_semi(); return True
        if t.text=="type":
            self.advance(); name_tok=self.cur()
            if name_tok.kind=="id": self.advance(); sk,sn=self.scope(ent); self.ctx.tag(name_tok.text, name_tok.line, "t", scope_kind=sk, scope_name=sn)
            self.skip_to_semi(); return True
        if t.text=="macro_rules":
            self.advance(); 
            if self.cur().text=="!": self.advance()
            name_tok=self.cur()
            if name_tok.kind=="id": self.advance(); self.ctx.tag(name_tok.text, name_tok.line, "M", scope_kind=self.scope(ent)[0], scope_name=self.scope(ent)[1])
            if self.cur().text=="{": self.pos=self.match(self.pos,"{","}")+1
            else: self.skip_to_semi()
            return True
        if t.text=="use":
            self.skip_to_semi(); return True
        if t.text=="union":
            # skip declaration
            self.advance(); 
            if self.cur().kind=="id": self.advance()
            if self.cur().text=="<": self.pos=self.match_angle(self.pos)+1
            if self.cur().text=="{": self.pos=self.match(self.pos,"{","}")+1
            else: self.skip_to_semi()
            return True
        if t.text=="let":
            self.skip_to_semi(); return True
        self.pos=save; return False
    def skip_to_semi(self):
        while not self.eof() and self.cur().text not in (";","}"):
            if self.cur().text=="{": self.pos=self.match(self.pos,"{","}")+1; continue
            self.advance()
        if self.cur().text==";": self.advance()
    def parse_fn(self, ent):
        fn_tok=self.advance() # fn
        name_tok=self.cur()
        if name_tok.kind!="id":
            # maybe operator? skip
            return True
        self.advance()
        if self.cur().text=="<": self.pos=self.match_angle(self.pos)+1
        sig="()"; oi=ci=None
        if self.cur().text=="(":
            oi=self.pos; ci=self.match(oi,"(",")"); self.pos=ci+1
        # return type until { ; or maybe where
        ret_tokens=[]; 
        if self.cur().text=="->":
            self.advance()
            while not self.eof() and self.cur().text not in ("{",";","where"):
                ret_tokens.append(self.cur().text); self.advance()
        ret_text=" ".join(ret_tokens) if False else "".join([(" "+x if ret_tokens and (x[0].isalnum() or x=="_") and (ret_tokens[-1][0].isalnum() or ret_tokens[-1]=="_") else x) for x in ret_tokens]) if ret_tokens else ""
        # Simplify return text from token joining using raw line if same line
        if oi is not None and ret_tokens:
            # use source segment after -> up to { or ; on same lines if possible
            # We'll construct with spaces between identifiers, keep & etc attached next
            rt=""
            for tok in ret_tokens:
                if not rt: rt=tok
                elif tok in ("<",">",",","::"): rt+=tok
                elif rt.endswith(("<","::",",")): rt+=tok
                elif tok=="&": rt+=" &" if False else " &"
                else: rt+=" "+tok if not rt.endswith("&") else tok
            ret_text=rt.strip()
            # For &T, original is "&T" no space
            ret_text=ret_text.replace("& ","&")
        if oi is not None: sig=self.sig_from(oi,ci,ret_text)
        kind="P" if ent and ent.scope_kind in ("implementation","interface") else "f"
        sk,sn=self.scope(ent)
        tag=self.ctx.tag(name_tok.text, name_tok.line, kind, scope_kind=sk, scope_name=sn, signature=sig)
        # where clause skip
        while not self.eof() and self.cur().text not in ("{",";","}"): self.advance()
        if self.cur().text=="{":
            end=self.match(self.pos,"{","}"); tag.end=self.tokens[end].line if False else None
            # Function end in Rust * ? Free functions had no end field in * outputs (only signature/roles). So leave end None.
            qpath=self.join_path(ent, name_tok.text) if kind=="f" else (ent.path+"::"+name_tok.text if ent else name_tok.text)
            fent= RustEntity(name_tok.text, qpath, "function")
            self.advance(); self.parse_items(fent)
            if self.cur().text=="}": self.advance()
        elif self.cur().text==";": self.advance()
        return True
    def parse_struct(self, ent):
        self.advance(); name_tok=self.cur();
        if name_tok.kind!="id": return True
        self.advance()
        if self.cur().text=="<": self.pos=self.match_angle(self.pos)+1
        sk,sn=self.scope(ent); tag=self.ctx.tag(name_tok.text, name_tok.line, "s", scope_kind=sk, scope_name=sn)
        qpath=self.join_path(ent, name_tok.text)
        sent=RustEntity(name_tok.text, qpath, "struct")
        if self.cur().text=="(":
            self.pos=self.match(self.pos,"(",")")+1
            if self.cur().text==";": self.advance()
            return True
        if self.cur().text=="{":
            self.advance(); self.parse_struct_fields(sent)
            if self.cur().text=="}": self.advance()
        elif self.cur().text==";": self.advance()
        return True
    def parse_struct_fields(self, sent):
        while not self.eof() and self.cur().text!="}":
            if self.cur().text in (",",";"): self.advance(); continue
            self.consume_modifiers()
            name_tok=self.cur()
            if name_tok.kind!="id": self.advance(); continue
            if self.cur(1).text!=":":
                self.advance(); continue
            self.advance(); self.advance() # name and :
            self.ctx.tag(name_tok.text, name_tok.line, "m", scope_kind="struct", scope_name=sent.path)
            # skip type to top comma or }
            depth=0
            while not self.eof():
                txt=self.cur().text
                if txt in ("<","[","(","{"): depth+=1
                elif txt in (">","]",")","}"):
                    if txt=="}" and depth==0: break
                    depth-=1
                if txt=="," and depth==0: break
                self.advance()
            if self.cur().text==",": self.advance()
    def parse_enum(self, ent):
        self.advance(); name_tok=self.cur()
        if name_tok.kind!="id": return True
        self.advance(); 
        if self.cur().text=="<": self.pos=self.match_angle(self.pos)+1
        sk,sn=self.scope(ent); self.ctx.tag(name_tok.text, name_tok.line, "g", scope_kind=sk, scope_name=sn)
        qpath=self.join_path(ent, name_tok.text)
        if self.cur().text=="{":
            self.advance()
            while not self.eof() and self.cur().text!="}":
                if self.cur().text in (",",";"): self.advance(); continue
                vt=self.cur()
                if vt.kind!="id": self.advance(); continue
                self.advance(); self.ctx.tag(vt.text, vt.line, "e", scope_kind="enum", scope_name=qpath)
                if self.cur().text=="(": self.pos=self.match(self.pos,"(",")")+1
                if self.cur().text=="{": self.pos=self.match(self.pos,"{","}")+1
                if self.cur().text=="=":
                    # skip assignment until comma at depth0
                    self.advance(); depth=0
                    while not self.eof():
                        txt=self.cur().text
                        if txt in ("(","[","{"): depth+=1
                        elif txt in (")","]","}"):
                            if txt=="}" and depth==0: break
                            depth-=1
                        if txt=="," and depth==0: break
                        self.advance()
            if self.cur().text=="}": self.advance()
        return True
    def parse_trait(self, ent):
        self.advance(); name_tok=self.cur()
        if name_tok.kind!="id": return True
        self.advance(); 
        if self.cur().text=="<": self.pos=self.match_angle(self.pos)+1
