            class_tag.anonymous=False # PHP anon class name is deterministic but not marked anonymous extra? Original * had no extras anonymous; keep false
            actx=PHPContext("class", anon, anon)
            self.advance(); self.parse_statements(actx)
            if self.cur().text=="}": self.advance()
            if self.cur().text==";": self.advance()
            return True
        # otherwise skip block
        self.pos=self.match(self.pos,"{","}")+1
        if self.cur().text==";": self.advance()
        return True

