# ---------- Simple language parsers (Sh, Perl, Lua, etc.) ----------
def strip_shell_line(line):
    return strip_ruby_line(line)

@parser_for("Sh", "Zsh")
def parse_sh(ctx):
    lines=lines_of(ctx)
    heredocs=[]
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=strip_shell_line(raw).strip()
        if heredocs:
            if stripped==heredocs[0]:
                tag=ctx.tag(stripped, lineno, "h", ref=True); tag.extras_list=["reference"]; heredocs.pop(0)
            continue
        if not stripped or stripped.startswith("#"): continue
        # Bats test handled for Bats in its parser; Sh functions etc
        # heredoc start on this line
        hd_names=re.findall(r"<<-?\s*['\"]?([A-Za-z_][A-Za-z0-9_]*)['\"]?", strip_shell_line(raw))
        for name in hd_names:
            ctx.tag(name, lineno, "h")
        # source
        m=re.match(r"^(?:source|\.)\s+['\"]?([^\s'\"]+)", stripped)
        if m:
            tag=ctx.tag(m.group(1), lineno, "s", ref=True); tag.extras_list=["reference"]
        # alias
        m=re.match(r"^alias\s+([A-Za-z_][\w.-]*)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "a"); 
        # functions
        m=re.match(r"^function\s+([A-Za-z_][A-Za-z0-9_-]*)", stripped)
        if m: ctx.tag(m.group(1), lineno, "f")
        else:
            m=re.match(r"^([A-Za-z_][A-Za-z0-9_-]*)\s*\(\s*\)\s*(.*)$", stripped)
            if m:
                rest=m.group(2).strip()
                if rest.startswith(("{","(")) or rest=="" :
                    if rest=="":
                        # look ahead for brace
                        for nxt in lines[idx+1:]:
                            ns=strip_shell_line(nxt).strip()
                            if not ns: continue
                            if ns.startswith(("{","(")): ctx.tag(m.group(1), lineno, "f")
                            break
                    else: ctx.tag(m.group(1), lineno, "f")
        heredocs.extend(hd_names)
    return

@parser_for("Bats")
def parse_bats(ctx):
    # Sh features plus test cases
    parse_sh(ctx)
    # Remove Sh tags? Bats uses its own parse in original with same functions etc plus tests. Duplicate tags would be deduped when identical; test tags:
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        m=re.match(r'\s*@test\s+["\']([^"\']+)["\']', raw)
        if m: ctx.tag(m.group(1), idx+1, "t")
    return

@parser_for("Perl")
def parse_perl(ctx):
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if stripped in ("__END__","__DATA__"): break
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^package\s+([\w:]+)\s*;", stripped)
        if m: ctx.tag(m.group(1), lineno, "p"); continue
        m=re.match(r"^use\s+constant\s+\{\s*(.*)\}", stripped)
        if m:
            for part in m.group(1).split(","):
                mm=re.match(r"\s*(\w+)\s*=>", part)
                if mm: ctx.tag(mm.group(1), lineno, "c")
            continue
        m=re.match(r"^use\s+constant\s+(\w+)\s*=>", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"^(?:use|no)\s+([\w:]+)", stripped)
        if m:
            tag=ctx.tag(m.group(1), lineno, "M", ref=True, roles="used" if stripped.startswith("use") else "unused"); tag.extras_list=["reference"]; continue
        m=re.match(r"^sub\s+(\w+)(.*)$", stripped)
        if m:
            rest=m.group(2).strip()
            is_decl=stripped.endswith(";") and "{" not in rest
            ctx.tag(m.group(1), lineno, "d" if is_decl else "s"); continue
        m=re.match(r"^format\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); continue
        m=re.match(r"^([A-Za-z_]\w*):\s", stripped)
        if m and "::" not in stripped.split(":")[0]: ctx.tag(m.group(1), lineno, "l"); continue
    return

@parser_for("Lua")
def parse_lua(ctx):
    lines=lines_of(ctx)
    in_long=False
    for idx, raw in enumerate(lines):
        lineno=idx+1
        line=raw
        # strip -- comments (simple)
        if "--" in line: line=line[:line.find("--")]
        stripped=line.strip()
        if not stripped: continue
        m=re.match(r"^(?:local\s+)?function\s+([A-Za-z_][\w.:]*)\s*\(", stripped)
        if m:
            full=m.group(1); parts=re.split(r"[.:]", full); name=parts[-1]
            if len(parts)>1: ctx.tag(name, lineno, "f", scope_kind="unknown", scope_name=parts[0])
            else: ctx.tag(name, lineno, "f")
            continue
        m=re.match(r"^local\s+([A-Za-z_]\w*)\s*=\s*function\b", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); continue
    return

