@parser_for("HTML")
def parse_html(ctx):
    lines=lines_of(ctx)
    guest_ranges=[]  # (start_idx,end_idx,lang)
    in_guest=None
    guest_start=None
    for idx, raw in enumerate(lines):
        lineno=idx+1
        # Guest range tracking
        lower=raw.lower()
        if re.search(r"<style\b", lower):
            in_guest="CSS"; guest_start=idx
        if re.search(r"<script\b", lower) and "src=" not in lower:
            in_guest="JavaScript"; guest_start=idx
        if in_guest and re.search(r"</(style|script)>", lower):
            guest_ranges.append((guest_start, idx, in_guest)); in_guest=None
        # anchors
        for m in re.finditer(r"<a\b[^>]*\bname\s*=\s*[\"']([^\"']+)[\"']", raw, re.I):
