            if "stylesheet" in raw.lower() or m.group(1).endswith(".css"):
                tag=ctx.tag(m.group(1), lineno, "C", ref=True, roles="extFile"); tag.extras_list=["reference"]
        # headings and title
        for level,kind in ((1,"h"),(2,"i"),(3,"j")):
