def parse_css_text(ctx, text_lines=None):
    lines=text_lines if text_lines is not None else lines_of(ctx)
    text="\n".join(lines)
    clean=strip_c_comments_strings(text)
    # scanner
    pos=0; line_no=1; buf=[]; buf_line=1; buf_started=False
    stack=[]  # contexts: at, keyframes, decl
    i=0
    def flush_selector(prelude, pline):
        prelude=" ".join(prelude.split())
        if not prelude: return
        if prelude.startswith("@"): return
        if stack and stack[-1]=="keyframes": return
        for sel in prelude.split(","):
            sel=sel.strip()
            if not sel: continue
            if "#" in sel: kind="i"
            elif "." in sel: kind="c"
            else: kind="s"
            ctx.tag(sel, pline, kind)
    while i<len(clean):
        c=clean[i]
