            line_no+=1; buf.append(c); i+=1; continue
        if not buf_started and not c.isspace():
            buf_started=True; buf_line=line_no
        if c=="{":
            prelude="".join(buf).strip(); buf=[]; buf_started=False
            if prelude.startswith("@"):
                name=prelude.split()[0].lower() if prelude.split() else "@"
                if "keyframes" in name: stack.append("keyframes")
                else: stack.append("at")
            else:
