                stack.append("decl")
            i+=1; continue
        if c==";":
            buf=[]; buf_started=False; i+=1; continue
        if c=="}":
            if stack: stack.pop()
            buf=[]; buf_started=False; i+=1; continue
        buf.append(c); i+=1
    return

