        letter,kindname=kinds[level]
        # pop >= level and set ends
        while stack and stack[-1]["level"]>=level:
            fr=stack.pop()
            if fr["tag"].end is None: fr["tag"].end=lineno-1
        scope_kind=""; scope_name=""
        if stack:
            scope_kind=stack[-1]["kind_name"]; scope_name='""'.join(fr["name"] for fr in stack)
        tag=ctx.tag(name, lineno, letter, scope_kind=scope_kind, scope_name=scope_name)
        stack.append({"level":level,"name":name,"kind_name":kindname,"tag":tag})
        return tag
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        # fences
        fm=re.match(r"^(```+|~~~+)", stripped)
        if fm:
            marker=fm.group(1)[0]
            if not in_fence: in_fence=True; fence_marker=marker
