        if re.match(r"^=+\s*$", stripped) and prev_text_idx is not None:
            name=lines[prev_text_idx].strip()
            if name: heading_tag(1, name, prev_text_idx+1)
            prev_text_idx=None; continue
        if re.match(r"^-+\s*$", stripped) and prev_text_idx is not None:
