        fm2=re.match(r"^\[\^([^\]]+)\]:", stripped)
        if fm2:
            scope_kind=""; scope_name=""
            if stack: scope_kind=stack[-1]["kind_name"]; scope_name='""'.join(fr["name"] for fr in stack)
