    for fr in stack:
        if fr["tag"].end is None: fr["tag"].end=last
    return

@parser_for("Make", "Automake")
def parse_make(ctx):
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        lineno=idx+1
        if raw.startswith("\t"): continue
        stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^(-?s?include)\s+(\S+)", stripped)
        if m:
            tag=ctx.tag(m.group(2), lineno, "I", ref=True); tag.extras_list=["reference"]; continue
        m=re.match(r"^define\s+(\S+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        m=re.match(r"^(?:export\s+)?([A-Za-z_][\w.-]*)\s*[:?+!]?=(?!=)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        # targets
        if ":" in stripped and "=" not in stripped.split(":")[0]:
            left=stripped.split(":",1)[0].strip()
            if left and not left.startswith((".PHONY",)):
                for name in left.split():
                    ctx.tag(name, lineno, "t")
            elif left.startswith(".PHONY"):
                # .PHONY targets themselves not tagged, but names after colon are existing targets references no
                pass
            continue
    return

@parser_for("CMake")
def parse_cmake(ctx):
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"(?i)^project\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "p"); continue
        m=re.match(r"(?i)^option\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "D"); continue
        m=re.match(r"(?i)^set\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
        m=re.match(r"(?i)^(add_executable|add_library|add_custom_target)\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(2), lineno, "t"); continue
        m=re.match(r"(?i)^function\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); continue
        m=re.match(r"(?i)^macro\s*\(\s*([^\s\)]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
    return

@parser_for("Vim")
def parse_vim(ctx):
    lines=lines_of(ctx)
    in_function=False
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith('"'): continue
        if re.match(r"^endfunction\b", stripped): in_function=False; continue
        m=re.match(r"^function!?\s+([^\s\(]+)\s*\(", stripped)
        if not m: m=re.match(r"^function!?\s+([^\s\(]+)$", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); in_function=True; continue
        if in_function: continue
        m=re.match(r"^let\s+([A-Za-z_][\w:.-]*)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
        m=re.match(r"^const\s+([A-Za-z_]\w*)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "C"); continue
        m=re.match(r"^command!?\s+([A-Z]\w*)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"^augroup\s+(\S+)", stripped)
        if m and m.group(1).upper()!="END": ctx.tag(m.group(1), lineno, "a"); continue
        m=re.match(r"^(?:[a-z]*)(?:noremap|map)\s+(\S+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
    return

@parser_for("XML")
def parse_xml(ctx):
    lines=lines_of(ctx)
    stack=[]  # element names
    for idx, raw in enumerate(lines):
        lineno=idx+1
        snapshot=list(stack)
        # process tags in line for generation (using snapshot)
        tag_events=[]
        # find XML tags ignoring comments and PI
        work=re.sub(r"<!--.*?-->", "", raw)
        for m in re.finditer(r"<(/?)([A-Za-z_][\w:.-]*)((?:\s+[^<>]*?)?)(/?)>", work):
            closing=bool(m.group(1)); elem=m.group(2); attrs=m.group(3) or ""; selfclose=bool(m.group(4))
            tag_events.append((closing,elem,selfclose))
            if closing: continue
            # id attr
            for am in re.finditer(r"\bid\s*=\s*[\"']([^\"']+)[\"']", attrs):
                if snapshot: xpath="/" + "/".join(snapshot+[elem]) + "/@id"
                else: xpath="/*" + (f"/{elem}" if False else "") + "/@id"
                # For nested in snapshot path, first component is root as stored; for self? implementation above matches
                if snapshot: xpath="/" + "/".join(snapshot+[elem]) + "/@id"
                else: xpath="/*/@id"
                # If this element is nested in root and snapshot has parent, path should include element: snapshot already parents, elem current
                tag=ctx.tag(am.group(1), lineno, "i"); tag.custom["xpath"]=xpath
            # xmlns attrs
            for am in re.finditer(r"\bxmlns:([\w.-]+)\s*=\s*[\"']([^\"']+)[\"']", attrs):
                tag=ctx.tag(am.group(1), lineno, "n"); tag.custom["uri"]=am.group(2)
            for am in re.finditer(r"\bxmlns\s*=\s*[\"']([^\"']+)[\"']", attrs):
                anon=ctx.anon_name("n").replace("__anon","ns",1)
                tag=ctx.tag(anon, lineno, "n", anonymous=True); tag.custom["uri"]=am.group(1)
        # update stack based events
        for closing,elem,selfclose in tag_events:
            if closing:
                if elem in stack:
                    # pop until elem
                    while stack and stack[-1]!=elem: stack.pop()
                    if stack: stack.pop()
            elif not selfclose:
                stack.append(elem)
    return

class JSONParseError(Exception): pass
@parser_for("JSON")
def parse_json(ctx):
    text="\n".join(lines_of(ctx))
    # tokenizer
    tokens=[]; i=0; line=1
    while i<len(text):
        c=text[i]
        if c=="\n": line+=1; i+=1; continue
        if c.isspace(): i+=1; continue
        if c in "{}[],:":
            tokens.append((c,line,c)); i+=1; continue
        if c=='"':
            start_line=line; j=i+1; esc=False
            while j<len(text):
                if text[j]=="\n": line+=1
                if esc: esc=False; j+=1; continue
                if text[j]=="\\": esc=True; j+=1; continue
                if text[j]=='"': break
                j+=1
            raw=text[i:j+1]
            try: val=json.loads(raw)
            except: val=raw[1:-1]
            tokens.append(("str",start_line,val)); i=j+1; continue
        # number / literal
        m=re.match(r"-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null", text[i:])
        if m:
            kind="num" if m.group(0)[0].isdigit() or m.group(0)[0]=="-" else ("bool" if m.group(0) in ("true","false") else "null")
            tokens.append((kind,line,m.group(0))); i+=len(m.group(0)); continue
        i+=1
    pos=0
    def peek():
        return tokens[pos] if pos<len(tokens) else (None,line,None)
    def parse_value(name, vline, parent_path, parent_kind):
        nonlocal pos
        kind, tline, val=peek()
        if kind is None: raise JSONParseError()
        # scope
        sk=""; sn=""
        if parent_kind and parent_path:
            sk=parent_kind; sn=parent_path
        if kind=="{":
            # object
            if name is not None: ctx.tag(name, vline, "o", scope_kind=sk, scope_name=sn)
            obj_path=((parent_path+"." if parent_path else "")+name) if name is not None else parent_path
            pos+=1
            while pos<len(tokens) and peek()[0]!="}":
                kkind,kline,kval=peek()
                if kkind!="str": raise JSONParseError()
                pos+=1
                if peek()[0]==":": pos+=1
                parse_value(str(kval), kline, obj_path, "object")
                if peek()[0]==",": pos+=1; continue
                break
            if peek()[0]=="}": pos+=1
            return
        if kind=="[":
            if name is not None: ctx.tag(name, vline, "a", scope_kind=sk, scope_name=sn)
            arr_path=((parent_path+"." if parent_path else "")+name) if name is not None else parent_path
            pos+=1; idx_elem=0
            while pos<len(tokens) and peek()[0]!="]":
                eline=peek()[1]
                parse_value(str(idx_elem), eline, arr_path, "array"); idx_elem+=1
                if peek()[0]==",": pos+=1; continue
                break
            if peek()[0]=="]": pos+=1
            return
        # scalar
        pos+=1
        if name is not None:
            letter={"str":"s","num":"n","bool":"b","null":"z"}.get(kind,"s")
            ctx.tag(name, vline, letter, scope_kind=sk, scope_name=sn)
        return
    try: parse_value(None, 1, "", "")
    except Exception: pass
    return

@parser_for("Yaml")
def parse_yaml(ctx):
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        lineno=idx+1
        for m in re.finditer(r"(?:^|[\s\-\{\[,])&([A-Za-z_][\w-]*)", raw):
            ctx.tag(m.group(1), lineno, "a")
        for m in re.finditer(r"(?:^|[\s:])\*([A-Za-z_][\w-]*)", raw):
            tag=ctx.tag(m.group(1), lineno, "a", ref=True, roles="alias"); tag.extras_list=["reference"]
    # Ansible subparser
    # Detect play: top-level list items with hosts:
    plays=[]; current=None
    for idx, raw in enumerate(lines):
        if re.match(r"^-\s", raw) or re.match(r"^-\s*$", raw):
            if current: plays.append(current)
            current={"line":idx+1,"name":None,"name_line":None,"has_hosts":False}
        if current is not None:
            m=re.match(r"^(?:-\s+|\s+)name:\s*(.+?)\s*$", raw)
            if m and current["name"] is None and re.match(r"^-", raw) or (m and raw.startswith("-")):
                current["name"]=m.group(1).strip('"\'' ); current["name_line"]=idx+1
            # More robust: a '- name:' line at indent 0
            m2=re.match(r"^-\s+name:\s*(.+?)\s*$", raw)
            if m2: current["name"]=m2.group(1).strip('"\'' ); current["name_line"]=idx+1
            if re.match(r"^\s+hosts\s*:", raw): current["has_hosts"]=True
    if current: plays.append(current)
    valid=[p for p in plays if p["name"] and p["has_hosts"]]
    for ii,p in enumerate(valid):
        end=valid[ii+1]["line"] if ii+1<len(valid) else len(lines)+1
        tag=Tag(name=p["name"], path=ctx.path, line_no=p["name_line"], line_text=ctx.lines[p["name_line"]-1][0], kind_letter="p", language="AnsiblePlaybook", end=end, line_has_newline=ctx.lines[p["name_line"]-1][1])
        tag.extras_list=["subparser"]; ctx.tags.append(tag)
    return

@parser_for("TOML")
def parse_toml(ctx):
    lines=lines_of(ctx)
    current_table=""; current_kind="table"; table_tag=None
    def close_table(next_line):
        nonlocal table_tag
        if table_tag is not None and table_tag.end is None: table_tag.end=next_line-1 if next_line>1 else table_tag.line_no
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^\[\[([^\]]+)\]\]", stripped)
        if m:
            close_table(lineno); name=m.group(1).strip(); current_table=name; current_kind="arraytable"; table_tag=ctx.tag(name, lineno, "a", end=None); continue
        m=re.match(r"^\[([^\]]+)\]", stripped)
        if m:
            close_table(lineno); name=m.group(1).strip(); current_table=name; current_kind="table"; table_tag=ctx.tag(name, lineno, "t", end=None); continue
        m=re.match(r"^([A-Za-z0-9_\.\-]+)\s*=(?!=)", stripped)
        if m:
            key=m.group(1)
            if current_table: ctx.tag(key, lineno, "K", scope_kind=current_kind, scope_name=current_table)
            else: ctx.tag(key, lineno, "K")
            continue
    close_table(len(lines)+1)
    if table_tag is not None and table_tag.end is None: table_tag.end=len(lines)
    return

@parser_for("Iniconf", "CMake", "PythonLoggingConfig")
def parse_iniconf(ctx):
    # CMake handled by its own parser: registration order matters? parser_for CMake above registers parse_cmake; this decorator only for other languages in list will be reassigned below by explicit check
    if ctx.language=="CMake":
        return parse_cmake(ctx)
    lines=lines_of(ctx); section=""
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith((";","#")): continue
        m=re.match(r"^\[([^\]]+)\]", stripped)
        if m: section=m.group(1); ctx.tag(section, lineno, "s"); continue
        m=re.match(r"^([^=\s]+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "k", scope_kind="section", scope_name=section)
    return

