@parser_for("Yaml")
def parse_yaml(ctx):
    lines=lines_of(ctx)
    for idx, raw in enumerate(lines):
        lineno=idx+1
        for m in re.finditer(r"(?:^|[\s\-\{\[,])&([A-Za-z_][\w-]*)", raw):
            ctx.tag(m.group(1), lineno, "a")
