@parser_for("TOML")
def parse_toml(ctx):
    lines=lines_of(ctx)
    current_table=""; current_kind="table"; table_tag=None
    def close_table(next_line):
        nonlocal table_tag
        if table_tag is not None and table_tag.end is None: table_tag.end=next_line-1 if next_line>1 else table_tag.line_no
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^\[\[([^\]]+)\]\]", stripped)
        if m:
            close_table(lineno); name=m.group(1).strip(); current_table=name; current_kind="arraytable"; table_tag=ctx.tag(name, lineno, "a", end=None); continue
        m=re.match(r"^\[([^\]]+)\]", stripped)
        if m:
            close_table(lineno); name=m.group(1).strip(); current_table=name; current_kind="table"; table_tag=ctx.tag(name, lineno, "t", end=None); continue
        m=re.match(r"^([A-Za-z0-9_\.\-]+)\s*=(?!=)", stripped)
        if m:
            key=m.group(1)
            if current_table: ctx.tag(key, lineno, "K", scope_kind=current_kind, scope_name=current_table)
            else: ctx.tag(key, lineno, "K")
            continue
    close_table(len(lines)+1)
    if table_tag is not None and table_tag.end is None: table_tag.end=len(lines)
    return

@parser_for("Iniconf", "CMake", "PythonLoggingConfig")
def parse_iniconf(ctx):
    # CMake handled by its own parser: registration order matters? parser_for CMake above registers parse_cmake; this decorator only for other languages in list will be reassigned below by explicit check
    if ctx.language=="CMake":
        return parse_cmake(ctx)
    lines=lines_of(ctx); section=""
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith((";","#")): continue
        m=re.match(r"^\[([^\]]+)\]", stripped)
        if m: section=m.group(1); ctx.tag(section, lineno, "s"); continue
        m=re.match(r"^([^=\s]+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "k", scope_kind="section", scope_name=section)
    return

