# ---------- Asciidoc, BibTeX, DosBatch, Tex, Lisp/Scheme/Clojure, Prolog ----------
@parser_for("Asciidoc")
def parse_asciidoc(ctx):
    lines=lines_of(ctx)
    stack=[]
    kinds=[None,("c","chapter"),("s","section"),("S","subsection"),("t","subsubsection"),("T","l4subsection"),("u","l5subsection")]
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        for m in re.finditer(r"\[\[([^\]]+)\]\]|\[#([^\]]+)\]", raw):
            ctx.tag(m.group(1) or m.group(2), lineno, "a")
        m=re.match(r"^(={1,6})\s+(.*?)\s*$", raw)
        if m:
            level=len(m.group(1)); name=m.group(2); letter,kindname=kinds[level]
            while stack and stack[-1][0]>=level: stack.pop()
            sk=stack[-1][2] if stack else ""; sn=stack[-1][1] if stack else ""
            ctx.tag(name, lineno, letter, scope_kind=sk, scope_name=sn)
            stack.append((level,name,kindname))
    return

@parser_for("BibTeX", "BibLaTeX")
def parse_bibtex(ctx):
    typemap={"article":"a","book":"b","booklet":"B","conference":"c","inbook":"i","incollection":"I","inproceedings":"j","manual":"m","mastersthesis":"M","misc":"n","phdthesis":"p","proceedings":"P","techreport":"t","unpublished":"u","string":"s"}
    for idx, raw in enumerate(lines_of(ctx)):
        m=re.match(r"\s*@(\w+)\s*[\{\(]\s*([^,=\s]+)", raw)
        if m:
            typ=m.group(1).lower(); letter=typemap.get(typ)
            if letter:
                if typ=="string":
                    # name before =
                    mm=re.match(r"\s*@\w+\s*[\{\(]\s*([A-Za-z_][\w]*)", raw); name=mm.group(1) if mm else m.group(2)
                else: name=m.group(2)
                ctx.tag(name, idx+1, letter)
    return

@parser_for("DosBatch")
def parse_dosbatch(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^:([A-Za-z_][\w]*)\s*$", stripped)
        if m: ctx.tag(m.group(1), lineno, "l"); continue
        m=re.match(r"^:([A-Za-z_][\w]*)\b", stripped)
        if m and not stripped.startswith("::"): ctx.tag(m.group(1), lineno, "l"); continue
        m=re.match(r"(?i)^set\s+(?:/[a-z]\s+)?\"?([A-Za-z_]\w*)=", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
    return

@parser_for("Tex")
def parse_tex(ctx):
    lines=lines_of(ctx)
    levels={"part":(0,"p","part"),"chapter":(1,"c","chapter"),"section":(2,"s","section"),"subsection":(3,"u","subsection"),"subsubsection":(4,"b","subsubsection"),"paragraph":(5,"P","paragraph"),"subparagraph":(6,"G","subparagraph")}
    stack=[]
    for idx, raw in enumerate(lines):
        lineno=idx+1
        for cmd, (rank,letter,kindname) in levels.items():
            m=re.search(r"\\"+cmd+r"(?:\s*\[[^\]]*\])?\s*\{([^{}]+)\}", raw)
            if m:
                while stack and stack[-1][0]>=rank: stack.pop()
                sk=stack[-1][3] if stack else ""; sn='""'.join(fr[2] for fr in stack) if stack else ""
                ctx.tag(m.group(1), lineno, letter, scope_kind=sk, scope_name=sn)
                stack.append((rank,m.group(1),m.group(1),kindname))
                # fix scope name composition: store name
                stack[-1]=(rank,m.group(1),m.group(1),kindname)
        for m in re.finditer(r"\\label\{([^{}]+)\}", raw): ctx.tag(m.group(1), lineno, "l")
        for m in re.finditer(r"\\bibitem(?:\[[^\]]*\])?\{([^{}]+)\}", raw): ctx.tag(m.group(1), lineno, "B")
        for m in re.finditer(r"\\newcommand\{?\\?([A-Za-z]+)\}?", raw): ctx.tag(m.group(1), lineno, "C")
        for m in re.finditer(r"\\newtheorem\{([^{}]+)\}", raw): ctx.tag(m.group(1), lineno, "t")
        for m in re.finditer(r"\\newcounter\{([^{}]+)\}", raw): ctx.tag(m.group(1), lineno, "N")
        for m in re.finditer(r"\\newenvironment\{([^{}]+)\}", raw): ctx.tag(m.group(1), lineno, "e")
        for m in re.finditer(r"\\DeclareMathOperator\{?\\?([A-Za-z]+)\}?", raw): ctx.tag(m.group(1), lineno, "o")
        for m in re.finditer(r"\\(?:input|include)\{([^{}]+)\}", raw):
            tag=ctx.tag(m.group(1), lineno, "i", ref=True); tag.extras_list=["reference"]
    return

LISP_KIND_MAP={"defun":"f","defmacro":"m","defvar":"v","defparameter":"p","defconstant":"c","defclass":"C","defgeneric":"G","defmethod":"M","deftype":"t","defstruct":"s"}
def parse_lisp_generic(ctx, language):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1
        for m in re.finditer(r"\(\s*(def[a-zA-Z\-]+|define(?:-syntax)?)\s+\(?\s*([^\s()]+)", raw):
            definer=m.group(1); raw_name=m.group(2)
            name=raw_name.strip(",\"'")
            if language=="Scheme":
                if definer=="define": kind="f"
                else: kind="Y"
            elif language=="Lisp":
                kind=LISP_KIND_MAP.get(definer.lower(), "Y")
            else: # EmacsLisp etc: use lisp map if exists else unknown
                kind=LISP_KIND_MAP.get(definer.lower(), "Y")
            tag=ctx.tag(name, lineno, kind)
            if kind=="Y": tag.custom["definer"]=definer.upper()
    return

@parser_for("Lisp")
def parse_lisp(ctx): parse_lisp_generic(ctx, "Lisp")
@parser_for("Scheme")
def parse_scheme(ctx): parse_lisp_generic(ctx, "Scheme")
@parser_for("EmacsLisp")
def parse_emacs_lisp(ctx): parse_lisp_generic(ctx, "Lisp")

@parser_for("Clojure")
def parse_clojure(ctx):
    ns=""
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^\(ns\s+([^\s\)]+)", stripped)
        if m: ns=m.group(1); ctx.tag(ns, lineno, "n"); continue
        m=re.match(r"^\(defn-?\s+([^\s\[\{]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "f", scope_kind="namespace", scope_name=ns); continue
        m=re.match(r"^\(defmacro\s+([^\s\[\{]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m", scope_kind="namespace", scope_name=ns); continue
    return

@parser_for("Prolog")
def parse_prolog(ctx):
    module=""
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^:-\s*module\s*\(\s*([a-z_]\w*)", stripped)
        if m: module=m.group(1); ctx.tag(module, lineno, "m"); continue
        m=re.match(r"^([a-z_]\w*)\s*(?:\((.*)\))?\s*(?:\.|:-)", stripped)
        if m and not stripped.startswith((":-","?-")):
            name=m.group(1); arity=0
            if m.group(2) is not None and m.group(2).strip():
                # count commas depth0
                depth=0; cnt=1
                for ch in m.group(2):
                    if ch in "([": depth+=1
                    elif ch in ")]": depth-=1
                    elif ch=="," and depth==0: cnt+=1
                arity=cnt
            sk="module" if module else ""; 
            tag=ctx.tag(name, lineno, "p", scope_kind=sk, scope_name=module); tag.custom["arity"]=arity
            tag2=ctx.tag(f"{name}/{arity}", lineno, "p", scope_kind=sk, scope_name=module); tag2.custom["arity"]=arity
    return

