        m=re.match(r"class_name\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"class\s+(\w+)\s*:", stripped)
        if m: ctx.tag(m.group(1), lineno, "c", scope_kind=scope_kind, scope_name=scope_name); stack.append((indent,m.group(1),"class")); continue
        m=re.match(r"signal\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "s", scope_kind=scope_kind, scope_name=scope_name); continue
        m=re.match(r"enum\s+(\w+)?\s*\{([^}]*)\}", stripped)
        if m:
            if m.group(1): ctx.tag(m.group(1), lineno, "g", scope_kind=scope_kind, scope_name=scope_name)
