            m=re.match(r"^(\w+)\s*=\s*-?\d+", stripped)
            if m: ctx.tag(m.group(1), lineno, "e", scope_kind="enum", scope_name=stack[-1][1]); 
        elif stack and stack[-1][0] in ("message","oneof","group"):
            # field: [repeated|optional|required] type name = num
            m=re.match(r"^(?:repeated\s+|optional\s+|required\s+)?(?:map\s*<[^>]+>|[\w.]+)\s+(\w+)\s*=\s*\d+", stripped)
