@parser_for("ReStructuredText")
def parse_rst(ctx):
    lines=lines_of(ctx)
    adorn_levels={}; stack=[]
    kinds=[("H","title"),("c","chapter"),("s","section"),("S","subsection"),("t","subsubsection")]
    for idx, raw in enumerate(lines):
        lineno=idx+1
        # Target / citation
        m=re.match(r"^\.\.\s+_([^:]+):", raw)
        if m: ctx.tag(m.group(1), lineno, "T"); continue
        m=re.match(r"^\.\.\s+\[([^\]]+)\]", raw)
        if m: ctx.tag(m.group(1), lineno, "C"); continue
        if idx+1<len(lines):
            under=lines[idx+1].strip()
            if raw.strip() and re.match(r"^([=\-~^\"'`:.#*+_])\1{2,}$", under):
                ch=under[0]
                if ch not in adorn_levels: adorn_levels[ch]=len(adorn_levels)
                level=adorn_levels[ch]
                if level>=len(kinds): level=len(kinds)-1
                letter,kindname=kinds[level]
                while stack and stack[-1][0]>=level: stack.pop()
                sk=stack[-1][2] if stack else ""; sn='""'.join(fr[1] for fr in stack) if stack else ""
                ctx.tag(raw.strip(), lineno, letter, scope_kind=sk, scope_name=sn)
                stack.append((level,raw.strip(),kindname))
    return

@parser_for("Robot")
def parse_robot(ctx):
    section=""
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^\*\*\*\s*(.+?)\s*\*\*\*", stripped)
        if m: section=m.group(1).lower(); continue
        if "test case" in section:
            if raw and not raw[0].isspace() and stripped: ctx.tag(stripped, lineno, "t")
        elif "keyword" in section:
            if raw and not raw[0].isspace() and stripped: ctx.tag(stripped, lineno, "k")
        elif "variable" in section:
            m=re.match(r"^([$@&%]\{[^}]+\})", stripped)
            if m: ctx.tag(m.group(1), lineno, "v")
    return

@parser_for("Thrift")
def parse_thrift(ctx):
    stack=[]
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^namespace\s+\S+\s+(\S+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "n"); continue
        m=re.match(r"^(struct|exception|union|service)\s+(\w+)\s*\{?", stripped)
        if m:
            letter={"struct":"s","exception":"x","union":"u","service":"v"}[m.group(1)]
            ctx.tag(m.group(2), lineno, letter)
            if "{" in stripped: stack.append((m.group(1),m.group(2)))
            continue
        m=re.match(r"^enum\s+(\w+)\s*\{?", stripped)
        if m: ctx.tag(m.group(1), lineno, "g"); 
        if m and "{" in stripped: stack.append(("enum",m.group(1)))
        if stack and stack[-1][0]=="enum":
            mm=re.match(r"^(\w+)\s*(?:=\s*\d+)?\s*[,;]?", stripped)
            if mm and stripped and not stripped.startswith("}"): ctx.tag(mm.group(1), lineno, "e", scope_kind="enum", scope_name=stack[-1][1])
        elif stack and stack[-1][0] in ("struct","exception","union"):
            mm=re.match(r"^\d+\s*:\s*(?:required\s+|optional\s+)?[\w.<>]+\s+(\w+)", stripped)
            if mm: ctx.tag(mm.group(1), lineno, "m", scope_kind=stack[-1][0], scope_name=stack[-1][1])
        elif stack and stack[-1][0]=="service":
            mm=re.match(r"^(?:[\w.<>]+)\s+(\w+)\s*\(", stripped)
            if mm: ctx.tag(mm.group(1), lineno, "f", scope_kind="service", scope_name=stack[-1][1])
        m=re.match(r"^typedef\s+[\w.<>]+\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^const\s+[\w.<>]+\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "C"); continue
        if stripped.startswith("}"):
            if stack: stack.pop()
    return

@parser_for("Basic")
