        m=re.match(r"(?i)^Type\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"(?i)^Enum\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "g"); continue
        m=re.match(r"(?i)^Dim\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
        m=re.match(r"^(\w+):\s*$", stripped)
        if m: ctx.tag(m.group(1), lineno, "l"); continue
    return

@parser_for("Forth")
