        m=re.match(r"signal\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "s", scope_kind=scope_kind, scope_name=scope_name); continue
        m=re.match(r"enum\s+(\w+)?\s*\{([^}]*)\}", stripped)
