                if nm: ctx.tag(nm.group(1), lineno, "e", scope_kind="enum", scope_name=m.group(1) or "")
            continue
        m=re.match(r"enum\s+(\w+)\s*:", stripped)
        if m: ctx.tag(m.group(1), lineno, "g"); continue
        m=re.match(r"const\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "C", scope_kind=scope_kind, scope_name=scope_name); continue
