            if ctx.opts.kind_enabled("GDScript","z"):
                for seg in m.group(2).split(","):
                    pm=re.match(r"\s*(\w+)", seg)
                    if pm: ctx.tag(pm.group(1), lineno, "z", scope_kind="member", scope_name=m.group(1), file_scope=True)
            continue
