        m=re.match(r"(?i)^class\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"(?i)^enum\s+(\w+)\s*\{([^}]*)\}", stripped)
        if m:
            ctx.tag(m.group(1), lineno, "g")
            for part in re.split(r"[,\n]", m.group(2)):
