@parser_for("Elm")
def parse_elm(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^module\s+([\w.]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        m=re.match(r"^type\s+alias\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "a"); continue
        m=re.match(r"^type\s+(\w+)[^=]*=\s*(.*)$", stripped)
        if m:
            ctx.tag(m.group(1), lineno, "t")
            for part in m.group(2).split("|"):
                cm=re.match(r"\s*([A-Z]\w*)", part)
                if cm: ctx.tag(cm.group(1), lineno, "c")
            continue
        m=re.match(r"^port\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "p"); continue
        if raw and not raw[0].isspace():
            m=re.match(r"^([a-z_]\w*)\b[^=]*=", stripped)
            if m and "::" not in stripped: ctx.tag(m.group(1), lineno, "f")
    return

