    return

@parser_for("Man", "Scdoc")
def parse_man(ctx):
    # Man uses .TH / .SH / .SS ; Scdoc uses # headings. Handle both by content
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^\.TH\s+\"?([^\s\"]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^\.SH\s+\"?(.+?)\"?$", stripped)
        if m: ctx.tag(m.group(1), lineno, "s"); continue
        m=re.match(r"^\.SS\s+\"?(.+?)\"?$", stripped)
        if m: ctx.tag(m.group(1), lineno, "S"); continue
        m=re.match(r"^(#{1,3})\s+(.*)$", stripped)
        if m: ctx.tag(m.group(2), lineno, "t" if len(m.group(1))==1 else ("s" if len(m.group(1))==2 else "S")); continue
    return

