@parser_for("D")
def parse_d_lang(ctx):
    # Add module/alias tags and run C parser on masked text
    lines=lines_of(ctx)
    masked=[]
    for idx, raw in enumerate(lines):
        stripped=raw.strip()
        m=re.match(r"^module\s+([\w.]+)\s*;", stripped)
        if m: ctx.tag(m.group(1), idx+1, "M"); masked.append(("",True)); continue
        m=re.match(r"^import\s+.*;", stripped)
        if m: masked.append(("",True)); continue
        m=re.match(r"^alias\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), idx+1, "a", file_scope=True); masked.append(("",True)); continue
        masked.append((raw, ctx.lines[idx][1] if idx<len(ctx.lines) else True))
    subctx=FileCtx(ctx.opts, ctx.path, "D", "", masked)
    try:
        parser=CParser(subctx); parser.parse()
        for tag in subctx.tags:
            if tag.file_scope: tag.file_extra=True
            ctx.tags.append(tag)
    except Exception: pass
    return

