        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"(?i)^(function|filter)\s+([A-Za-z_][\w-]*)", stripped)
        if m: ctx.tag(m.group(2), lineno, "f" if m.group(1).lower()=="function" else "i"); continue
        m=re.match(r"(?i)^class\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"(?i)^enum\s+(\w+)\s*\{([^}]*)\}", stripped)
        if m:
            ctx.tag(m.group(1), lineno, "g")
            for part in re.split(r"[,\n]", m.group(2)):
                nm=re.match(r"\s*(\w+)", part)
                if nm: ctx.tag(nm.group(1), lineno, "e", scope_kind="enum", scope_name=m.group(1))
            continue
        m=re.match(r"^\$(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
    return

@parser_for("Protobuf")
def parse_protobuf(ctx):
    lines=lines_of(ctx); stack=[]
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        # close contexts if line starts }
        # package
        m=re.match(r"^package\s+([\w.]+)\s*;", stripped)
        if m: ctx.tag(m.group(1), lineno, "p"); continue
        m=re.match(r"^(message|enum|service|oneof|group)\s+(\w+)\s*\{?", stripped)
        if m:
            typ=m.group(1); name=m.group(2); letter={"message":"m","enum":"g","service":"s","oneof":"o","group":"G"}[typ]
            ctx.tag(name, lineno, letter)
            if "{" in stripped: stack.append((typ,name))
            continue
        if stripped=="RPC" : pass
        m=re.match(r"^rpc\s+(\w+)\s*\(", stripped)
        if m: ctx.tag(m.group(1), lineno, "r", scope_kind="service", scope_name=stack[-1][1] if stack else ""); continue
        if stack and stack[-1][0]=="enum":
            m=re.match(r"^(\w+)\s*=\s*-?\d+", stripped)
            if m: ctx.tag(m.group(1), lineno, "e", scope_kind="enum", scope_name=stack[-1][1]); 
        elif stack and stack[-1][0] in ("message","oneof","group"):
            # field: [repeated|optional|required] type name = num
            m=re.match(r"^(?:repeated\s+|optional\s+|required\s+)?(?:map\s*<[^>]+>|[\w.]+)\s+(\w+)\s*=\s*\d+", stripped)
            if m: ctx.tag(m.group(1), lineno, "f", scope_kind="message", scope_name=stack[-1][1])
        # brace tracking simplistic
        if stripped.endswith("{") and not re.match(r"^(message|enum|service|oneof|group)\b", stripped):
            stack.append(("block",""))
        if stripped.startswith("}"):
            if stack: stack.pop()
    return

@parser_for("Terraform", "TerraformVariables")
def parse_terraform(ctx):
    lines=lines_of(ctx); stack=[]
    for idx, raw in enumerate(lines):
        lineno=idx+1; stripped=raw.strip()
        if stripped.startswith("}"):
            if stack: stack.pop()
            continue
        if stack and stack[-1]=="locals":
            m=re.match(r"^(\w+)\s*=", stripped)
            if m: ctx.tag(m.group(1), lineno, "l")
            if stripped.endswith("{"): stack.append("block")
            continue
        m=re.match(r"^(resource|data)\s+\"([^\"]+)\"\s+\"([^\"]+)\"", stripped)
        if m: ctx.tag(f"{m.group(2)}.{m.group(3)}", lineno, "r" if m.group(1)=="resource" else "d")
        else:
            m=re.match(r"^(variable|provider|module|output)\s+\"([^\"]+)\"", stripped)
            if m: ctx.tag(m.group(2), lineno, {"variable":"v","provider":"p","module":"m","output":"o"}[m.group(1)])
            elif re.match(r"^locals\s*\{", stripped):
                if stripped.endswith("{"): stack.append("locals"); continue
        if stripped.endswith("{"): stack.append("block")
    return

@parser_for("Julia")
def parse_julia(ctx):
    in_struct=None
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^module\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "n"); continue
        m=re.match(r"^(?:mutable\s+)?struct\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "s"); in_struct=m.group(1); continue
        if stripped=="end": in_struct=None; continue
        if in_struct:
            m=re.match(r"^(\w+)\s*(?:::.*)?$", stripped)
            if m and stripped and not stripped.startswith(("#",)): ctx.tag(m.group(1), lineno, "g", scope_kind="struct", scope_name=in_struct); continue
        m=re.match(r"^function\s+(\w+)\s*\(([^)]*)\)", stripped)
        if m: ctx.tag(m.group(1), lineno, "f", signature=f"({m.group(2)})"); continue
        m=re.match(r"^macro\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        m=re.match(r"^const\s+(?:[A-Za-z_]\w*\s*,\s*)*([A-Z_]\w*)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"^(?:abstract\s+type|primitive\s+type)\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^(\w+)\s*\([^)]*\)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); continue
    return

@parser_for("MatLab")
def parse_matlab(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("%"): continue
        m=re.match(r"^classdef\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"^function\b\s*(.*)$", stripped)
        if m:
            rest=m.group(1)
            if "=" in rest:
                after=rest.split("=",1)[1].strip(); nm=re.match(r"(\w+)\s*\(", after)
            else: nm=re.match(r"(\w+)\s*\(", rest) or re.match(r"(\w+)", rest)
            if nm: ctx.tag(nm.group(1), lineno, "f")
            continue
    return

@parser_for("JavaProperties")
def parse_java_properties(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        stripped=raw.strip()
        if not stripped or stripped.startswith(("#","!")): continue
        m=re.match(r"^([^=:\s]+)\s*[=:]", stripped)
        if m: ctx.tag(m.group(1), idx+1, "k")
    return

@parser_for("GoMod")
def parse_gomod(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        m=re.match(r"\s*module\s+(\S+)", raw)
        if m: ctx.tag(m.group(1), idx+1, "m"); break
    return

@parser_for("Meson")
def parse_meson(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^project\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "P"); continue
        m=re.match(r"^subdir\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "S"); continue
        m=re.match(r"^(executable|library|shared_library|static_library|both_libraries|shared_module)\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(2), lineno, "B"); continue
        m=re.match(r"^custom_target\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"^test\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^benchmark\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "b"); continue
        m=re.match(r"^run_target\s*\(\s*['\"]([^'\"]+)['\"]", stripped)
        if m: ctx.tag(m.group(1), lineno, "r"); continue
        m=re.match(r"^(\w+)\s*=\s*configuration_data\s*\(", stripped)
        if m: ctx.tag(m.group(1), lineno, "D"); continue
        m=re.match(r"^(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "V"); continue
    return

@parser_for("Passwd")
def parse_passwd(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        parts=raw.rstrip("\n").split(":")
        if len(parts)>=7 and parts[0]:
            tag=ctx.tag(parts[0], idx+1, "u"); tag.custom["home"]=parts[5]; tag.custom["shell"]=parts[6]
    return

@parser_for("PkgConfig")
def parse_pkgconfig(ctx):
    # package name guessed from filename
    base=os.path.basename(ctx.path)
    pkgname=base[:-3] if base.endswith(".pc") else base
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith("#"): continue
        m=re.match(r"^Name:\s*(.+)$", stripped)
        if m: ctx.tag(m.group(1).strip(), lineno, "N"); continue
        m=re.match(r"^(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
    if pkgname and ctx.opts.extra_enabled_name("guessedFromFileName"):
        ctx.tag(pkgname, 1, "p")
    return

@parser_for("SystemdUnit")
def parse_systemd(ctx):
    # Like ini sections but kind u for unit names in section headers? Use section names
    for idx, raw in enumerate(lines_of(ctx)):
        m=re.match(r"^\[([^\]]+)\]", raw.strip())
        if m: ctx.tag(m.group(1), idx+1, "u")
    return

@parser_for("ReStructuredText")
def parse_rst(ctx):
    lines=lines_of(ctx)
    adorn_levels={}; stack=[]
    kinds=[("H","title"),("c","chapter"),("s","section"),("S","subsection"),("t","subsubsection")]
    for idx, raw in enumerate(lines):
        lineno=idx+1
        # Target / citation
        m=re.match(r"^\.\.\s+_([^:]+):", raw)
        if m: ctx.tag(m.group(1), lineno, "T"); continue
        m=re.match(r"^\.\.\s+\[([^\]]+)\]", raw)
        if m: ctx.tag(m.group(1), lineno, "C"); continue
        if idx+1<len(lines):
            under=lines[idx+1].strip()
            if raw.strip() and re.match(r"^([=\-~^\"'`:.#*+_])\1{2,}$", under):
                ch=under[0]
                if ch not in adorn_levels: adorn_levels[ch]=len(adorn_levels)
                level=adorn_levels[ch]
                if level>=len(kinds): level=len(kinds)-1
                letter,kindname=kinds[level]
                while stack and stack[-1][0]>=level: stack.pop()
                sk=stack[-1][2] if stack else ""; sn='""'.join(fr[1] for fr in stack) if stack else ""
                ctx.tag(raw.strip(), lineno, letter, scope_kind=sk, scope_name=sn)
                stack.append((level,raw.strip(),kindname))
    return

@parser_for("Robot")
def parse_robot(ctx):
    section=""
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^\*\*\*\s*(.+?)\s*\*\*\*", stripped)
        if m: section=m.group(1).lower(); continue
        if "test case" in section:
            if raw and not raw[0].isspace() and stripped: ctx.tag(stripped, lineno, "t")
        elif "keyword" in section:
            if raw and not raw[0].isspace() and stripped: ctx.tag(stripped, lineno, "k")
        elif "variable" in section:
            m=re.match(r"^([$@&%]\{[^}]+\})", stripped)
            if m: ctx.tag(m.group(1), lineno, "v")
    return

@parser_for("Thrift")
def parse_thrift(ctx):
    stack=[]
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^namespace\s+\S+\s+(\S+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "n"); continue
        m=re.match(r"^(struct|exception|union|service)\s+(\w+)\s*\{?", stripped)
        if m:
            letter={"struct":"s","exception":"x","union":"u","service":"v"}[m.group(1)]
            ctx.tag(m.group(2), lineno, letter)
            if "{" in stripped: stack.append((m.group(1),m.group(2)))
            continue
        m=re.match(r"^enum\s+(\w+)\s*\{?", stripped)
        if m: ctx.tag(m.group(1), lineno, "g"); 
        if m and "{" in stripped: stack.append(("enum",m.group(1)))
        if stack and stack[-1][0]=="enum":
            mm=re.match(r"^(\w+)\s*(?:=\s*\d+)?\s*[,;]?", stripped)
            if mm and stripped and not stripped.startswith("}"): ctx.tag(mm.group(1), lineno, "e", scope_kind="enum", scope_name=stack[-1][1])
        elif stack and stack[-1][0] in ("struct","exception","union"):
            mm=re.match(r"^\d+\s*:\s*(?:required\s+|optional\s+)?[\w.<>]+\s+(\w+)", stripped)
            if mm: ctx.tag(mm.group(1), lineno, "m", scope_kind=stack[-1][0], scope_name=stack[-1][1])
        elif stack and stack[-1][0]=="service":
            mm=re.match(r"^(?:[\w.<>]+)\s+(\w+)\s*\(", stripped)
            if mm: ctx.tag(mm.group(1), lineno, "f", scope_kind="service", scope_name=stack[-1][1])
        m=re.match(r"^typedef\s+[\w.<>]+\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^const\s+[\w.<>]+\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "C"); continue
        if stripped.startswith("}"):
            if stack: stack.pop()
    return

@parser_for("Basic")
def parse_basic(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        if not stripped or stripped.startswith(("'","REM ")): continue
        m=re.match(r"(?i)^(Function|Sub)\s+(\w+)", stripped)
        if m: ctx.tag(m.group(2), lineno, "f"); continue
        m=re.match(r"(?i)^Const\s+(\w+)\s*=", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
        m=re.match(r"(?i)^Type\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"(?i)^Enum\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "g"); continue
        m=re.match(r"(?i)^Dim\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
        m=re.match(r"^(\w+):\s*$", stripped)
        if m: ctx.tag(m.group(1), lineno, "l"); continue
    return

@parser_for("Forth")
def parse_forth(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^:\s+(\S+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "w"); continue
        m=re.match(r"(?i)^VARIABLE\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
        m=re.match(r"^\S+\s+(?i:CONSTANT)\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "c"); continue
    return

@parser_for("Elm")
def parse_elm(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^module\s+([\w.]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        m=re.match(r"^type\s+alias\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "a"); continue
        m=re.match(r"^type\s+(\w+)[^=]*=\s*(.*)$", stripped)
        if m:
            ctx.tag(m.group(1), lineno, "t")
            for part in m.group(2).split("|"):
                cm=re.match(r"\s*([A-Z]\w*)", part)
                if cm: ctx.tag(cm.group(1), lineno, "c")
            continue
        m=re.match(r"^port\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "p"); continue
        if raw and not raw[0].isspace():
            m=re.match(r"^([a-z_]\w*)\b[^=]*=", stripped)
            if m and "::" not in stripped: ctx.tag(m.group(1), lineno, "f")
    return

@parser_for("Eiffel")
def parse_eiffel(ctx):
    current_class=""
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"(?i)^class\s+(\w+)", stripped)
        if m: current_class=m.group(1); ctx.tag(current_class, lineno, "c"); continue
        m=re.match(r"^([a-z_]\w*)\s*(?:\([^)]*\))?\s*(?::\s*\w+\s*)?(?:is\s+)?(?:do|once|external|deferred)\b", stripped)
        if m and current_class: ctx.tag(m.group(1), lineno, "f", scope_kind="class", scope_name=current_class)
    return

@parser_for("NSIS")
def parse_nsis(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"(?i)^SectionGroup\s+\"?([^\"]+)\"?", stripped)
        if m: ctx.tag(m.group(1), lineno, "S"); continue
        m=re.match(r"(?i)^Section\s+\"?([^\"]+)\"?", stripped)
        if m: ctx.tag(m.group(1).strip(), lineno, "s"); continue
        m=re.match(r"(?i)^Function\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "f"); continue
        m=re.match(r"(?i)^!define\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "d"); continue
        m=re.match(r"(?i)^!macro\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "m"); continue
        m=re.match(r"(?i)^Var\s+(\w+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "v"); continue
    return

@parser_for("Man", "Scdoc")
def parse_man(ctx):
    # Man uses .TH / .SH / .SS ; Scdoc uses # headings. Handle both by content
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        m=re.match(r"^\.TH\s+\"?([^\s\"]+)", stripped)
        if m: ctx.tag(m.group(1), lineno, "t"); continue
        m=re.match(r"^\.SH\s+\"?(.+?)\"?$", stripped)
        if m: ctx.tag(m.group(1), lineno, "s"); continue
        m=re.match(r"^\.SS\s+\"?(.+?)\"?$", stripped)
        if m: ctx.tag(m.group(1), lineno, "S"); continue
        m=re.match(r"^(#{1,3})\s+(.*)$", stripped)
        if m: ctx.tag(m.group(2), lineno, "t" if len(m.group(1))==1 else ("s" if len(m.group(1))==2 else "S")); continue
    return

@parser_for("Pod")
def parse_pod(ctx):
    for idx, raw in enumerate(lines_of(ctx)):
        m=re.match(r"^=head1\s+(.*)$", raw)
        if m: ctx.tag(m.group(1), idx+1, "c"); continue
        m=re.match(r"^=head2\s+(.*)$", raw)
        if m: ctx.tag(m.group(1), idx+1, "s"); continue
        m=re.match(r"^=head3\s+(.*)$", raw)
        if m: ctx.tag(m.group(1), idx+1, "S"); continue
        m=re.match(r"^=head4\s+(.*)$", raw)
        if m: ctx.tag(m.group(1), idx+1, "t"); continue
    return

@parser_for("YACC")
def parse_yacc(ctx):
    in_rules=False
    for idx, raw in enumerate(lines_of(ctx)):
        lineno=idx+1; stripped=raw.strip()
        if stripped=="%%": in_rules=not in_rules; continue
        for m in re.finditer(r"%token\s+([A-Z_][A-Z0-9_]*)", stripped): ctx.tag(m.group(1), lineno, "t")
        if in_rules:
            m=re.match(r"^([a-z_]\w*)\s*:", stripped)
            if m: ctx.tag(m.group(1), lineno, "l")
    return

@parser_for("M4")
def parse_m4(ctx):
